window.TBS_DATA={"meta":{"schema":"terra-prep-tbs/1","count":24,"law_asof":"2026-09-29"},"items":[{"id":"REG-I-T-001","area":"I","format":"numeric_table","difficulty":2,"est_minutes":10,"testable_from":"2026-01-01","law_asof":"2026-09-29","law_note":"","cite":["IRC §6651(a)(1)","IRC §6651(a)(2)","IRC §6651(c)(1)"],"blueprint":{"area":"I","group":"C","topic":"Federal tax procedures: penalties","task":"Compute failure-to-file and failure-to-pay penalties","skill":"Application"},"params":{"tax":31000,"wh":17000},"vary":{"tax":[26000,29000,31000,34000,37000,40000],"wh":[12000,17000,20000]},"guards":["bal >= 6000"],"derived":[["bal","tax-wh"],["ftp7","rnd(bal*0.005*7)"]],"title":"Late-filing and late-payment penalties","scenario":"Priya Nair, a calendar-year individual, did not request an extension for her 2025 Form 1040, which was due April 15, 2026. She has never been late before and no exception (reasonable cause, military, disaster) applies.","task":"Using Exhibits 1 and 2, compute the penalties assessed under the failure-to-file and failure-to-pay provisions. Ignore interest, the minimum failure-to-file penalty, and any estimated-tax penalty. Round to the nearest dollar.","exhibits":[{"id":"e1","title":"Return summary (2025 Form 1040)","kind":"return_excerpt","body":[["Total tax (line 24)","${tax:,}"],["Federal income tax withheld","${wh:,}"],["Estimated payments","$0"],["Balance due shown on return","${bal:,}"]]},{"id":"e2","title":"Filing and payment history","kind":"notes","body":"Scenario A: Priya filed the return and paid the full balance due on August 3, 2026.\nScenario B (alternative facts): Priya filed the return and paid the full balance due on November 10, 2026.\nIn both scenarios, no part of the balance was paid before the filing date and no penalty was abated."}],"cells":[{"id":"c1","kind":"number","label":"Scenario A: number of months (or partial months) the return and payment were late","expr":"4","fmt":"n","tol":0,"why":"A partial month counts as a full month. April 16 to May 15 is month 1; July 16 to August 15 is month 4, and August 3 falls in month 4.","steps":["Month 1 ends May 15; month 2 ends June 15; month 3 ends July 15","August 3 is inside month 4 (July 16 to August 15)","Answer: 4"],"hints":["Each month or part of a month counts in full.","Count month boundaries from the April 16 start: the 15th of each following month."],"traps":[{"expr":"3","msg":"You counted whole months only. A partial month counts as a full month."}],"ecf":false,"cite":"IRC §6651(a)","points":1},{"id":"c2","kind":"number","label":"Scenario A: failure-to-file penalty","expr":"bal*(0.05-0.005)*c1","fmt":"$","tol":1,"why":"The failure-to-file penalty is 5% per month, but it is reduced by the 0.5% failure-to-payment penalty for each month both apply. Net 4.5% x 4 months x ${bal:,}.","steps":["Net monthly FTF rate = 5.0% - 0.5% = 4.5%","4.5% x {c1} months x ${bal:,} = ${c2:,}"],"hints":["Two penalties overlap in the early months. What happens to the 5% rate?","Net FTF rate is 4.5% per month while the FTP penalty is also running."],"traps":[{"expr":"bal*0.05*c1","msg":"You used the full 5% and did not reduce it by the 0.5% FTP penalty (the FTP and FTF penalties overlap)."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/6651","points":1},{"id":"c3","kind":"number","label":"Scenario A: failure-to-pay penalty","expr":"bal*0.005*c1","fmt":"$","tol":1,"why":"Failure to pay is 0.5% of the unpaid tax per month or partial month, up to 25%.","steps":["0.5% x {c1} months x ${bal:,} = ${c3:,}"],"hints":["The FTP rate is small; it runs for each month the tax is unpaid.","0.5% per month or part of a month."],"traps":[],"ecf":true,"points":1},{"id":"c4","kind":"number","label":"Scenario A: total penalties","expr":"c2+c3","fmt":"$","tol":1,"why":"Total = FTF + FTP. Combined they equal 5% per month, or {c1} x 5% x ${bal:,}.","steps":["${c2:,} + ${c3:,} = ${c4:,}","Check: 5% x {c1} x ${bal:,} = ${c4:,}"],"hints":["Add the two penalties.","Combined rate for the first five months is 5% per month."],"traps":[],"ecf":true,"points":1},{"id":"c5","kind":"number","label":"Scenario B (filed November 10, 2026): failure-to-file penalty","expr":"bal*0.045*min(7,5)","fmt":"$","tol":1,"why":"November 10 is month 7 (October 16 to November 15). The FTF penalty stops after 5 months (25% cap; net 4.5% x 5 = 22.5% while overlapping FTP).","steps":["Months late = 7; FTF applies only 5 months","4.5% x 5 x ${bal:,} = ${c5:,}"],"hints":["The failure-to-file penalty has a maximum number of months.","FTF caps at 25% total (5 months at 5%). Only 5 months of net 4.5% apply here."],"traps":[{"expr":"bal*0.045*7","msg":"You applied the FTF penalty for all 7 months. It caps at 5 months."}],"ecf":true,"points":1},{"id":"c6","kind":"number","label":"Scenario B: total penalties (FTF + FTP)","expr":"c5+bal*0.005*7","fmt":"$","tol":1,"why":"FTP keeps running for all 7 months (0.5% x 7 = 3.5%; the cap is 25% after 50 months). Total = FTF {c5:,} + FTP.","steps":["FTP = 0.5% x 7 x ${bal:,} = ${ftp7:,}","Total = ${c5:,} + ${ftp7:,} = ${c6:,}"],"hints":["FTP is not capped until much later.","FTP months = 7; total penalty rate = 22.5% + 3.5% = 26%."],"traps":[{"expr":"bal*0.05*7","msg":"You used 5% for all 7 months."}],"ecf":true,"points":1}]},{"id":"REG-I-T-002","area":"I","format":"document_review","difficulty":2,"est_minutes":12,"testable_from":"2026-01-01","law_asof":"2026-09-29","law_note":"","cite":["31 CFR §10.21","31 CFR §10.29","31 CFR §10.30","31 CFR §10.34","IRC §6694"],"blueprint":{"area":"I","group":"B","topic":"Circular 230 and preparer penalties","task":"Identify practitioner duties and preparer penalties","skill":"Analysis"},"params":{},"vary":{},"guards":[],"derived":[],"title":"Circular 230 practice memo review","scenario":"You are a senior at Halvorsen & Wu, CPAs, a firm that prepares individual and business returns. The firm's tax director drafted a memo to staff on Treasury Department Circular 230 and preparer penalties. You review it before it is distributed.","task":"For each numbered statement in the memo, choose the option that makes the statement correct. Choose 'Keep as written' if the statement is already correct.","exhibits":[{"id":"e1","title":"Draft staff memo","kind":"memo","body":"TO: Tax staff    FROM: Tax Director    RE: Practice standards (draft)\n\n1. When a client's prior-year depreciation schedule conflicts with this year's asset list, a practitioner who has relied on the client for years may rely on the schedule without inquiry.\n2. If we learn that a client omitted income from a previously filed return, we must promptly advise the client of the omission and the consequences, but we are not required to file an amended return or notify the IRS.\n3. Written informed consent for a conflict of interest must be retained and available to the IRS for at least 24 months after the representation ends.\n4. A practitioner who publishes a fee schedule must adhere to the published fees for at least 90 calendar days after the last date of publication.\n5. The penalty for a return-preparer understatement caused by an unreasonable position (without willful or reckless conduct) is the greater of $500 or 25% of the income derived from the return.\n6. For an income tax return position that is disclosed on the return (and is not a tax shelter or reportable transaction), a preparer needs at least a reasonable basis to avoid the return-preparer penalty."},{"id":"e2","title":"Firm policy note","kind":"notes","body":"Assume all engagements are for federal income tax return preparation by a CPA who is a practitioner under Circular 230 and a tax return preparer under the Code."}],"cells":[{"id":"c1","kind":"dropdown","label":"Statement 1: reliance on client information","options":["Keep as written","Revise: the practitioner must make reasonable inquiries when information appears incorrect, inconsistent, or incomplete","Revise: the practitioner must independently audit every client figure against source documents"],"answer":"Revise: the practitioner must make reasonable inquiries when information appears incorrect, inconsistent, or incomplete","why":"A practitioner may rely in good faith on client information without verifying it, but may not ignore the implications of information known to him or her and must make reasonable inquiries when information appears incorrect, inconsistent, or incomplete (Circular 230 §10.34(d)).","steps":[],"hints":["Good-faith reliance is allowed. What limits it?","Look at the words 'appears incorrect, inconsistent, or incomplete'."],"wrong_msgs":{"Keep as written":"Reliance is not unlimited. A known conflict triggers a duty of reasonable inquiry.","Revise: the practitioner must independently audit every client figure against source documents":"Overstated. There is no duty to audit everything; the duty is reasonable inquiry when a red flag appears."},"cite":"31 CFR §10.34(d)","link":"https://www.law.cornell.edu/cfr/text/31/10.34","points":1,"opts0":["Revise: the practitioner must make reasonable inquiries when information appears incorrect, inconsistent, or incomplete","Revise: the practitioner must independently audit every client figure against source documents","Keep as written"]},{"id":"c2","kind":"dropdown","label":"Statement 2: discovered error on a prior return","options":["Keep as written","Revise: the practitioner must file an amended return without the client's consent","Revise: the practitioner must report the omission to the IRS within 30 days"],"answer":"Keep as written","why":"Section 10.21 requires prompt advice to the client of the noncompliance, error, or omission and its consequences (including penalties). It does not require the practitioner to amend the return or disclose to the IRS, and the confidentiality rule of IRC §7216 generally prohibits disclosure without the client's consent.","steps":[],"hints":["Think about who decides whether to correct the return.","Advising the client is required; acting on the client's behalf without consent is not."],"wrong_msgs":{"Revise: the practitioner must file an amended return without the client's consent":"The practitioner cannot amend a client's return without the client's consent.","Revise: the practitioner must report the omission to the IRS within 30 days":"There is no duty to report the client to the IRS; disclosure is generally prohibited without consent."},"cite":"31 CFR §10.21","link":"https://www.law.cornell.edu/cfr/text/31/10.21","points":1,"opts0":["Keep as written","Revise: the practitioner must report the omission to the IRS within 30 days","Revise: the practitioner must file an amended return without the client's consent"]},{"id":"c3","kind":"dropdown","label":"Statement 3: retention period for conflict-of-interest consent","options":["Keep as written","Revise: 12 months","Revise: 36 months"],"answer":"Revise: 36 months","why":"Under §10.29(c), the written informed consent must be retained by the practitioner and made available to the IRS for at least 36 months after the conclusion of the representation.","steps":[],"hints":["A three-year window matches the general assessment period.","The regulation says at least 36 months."],"wrong_msgs":{"Keep as written":"24 months is too short; the requirement is 36 months.","Revise: 12 months":"12 months is too short; the requirement is 36 months."},"cite":"31 CFR §10.29(c)","link":"https://www.law.cornell.edu/cfr/text/31/10.29","points":1,"opts0":["Revise: 12 months","Revise: 36 months","Keep as written"]},{"id":"c4","kind":"dropdown","label":"Statement 4: published fee schedules","options":["Keep as written","Revise: 30 calendar days","Revise: 12 months"],"answer":"Revise: 30 calendar days","why":"A practitioner may publish fee information but must adhere to published fees for at least 30 calendar days after the last date of publication (Circular 230 §10.30(b)).","steps":[],"hints":["Advertising rule; the period is short.","It is a 30-day rule."],"wrong_msgs":{"Keep as written":"90 days overstates the requirement. It is 30 calendar days.","Revise: 12 months":"A year is far longer than the rule. It is 30 calendar days."},"cite":"31 CFR §10.30(b)","link":"https://www.law.cornell.edu/cfr/text/31/10.30","points":1,"opts0":["Revise: 12 months","Keep as written","Revise: 30 calendar days"]},{"id":"c5","kind":"dropdown","label":"Statement 5: preparer penalty amount, unreasonable position","options":["Keep as written","Revise: the greater of $1,000 or 50% of the income derived","Revise: the greater of $5,000 or 75% of the income derived"],"answer":"Revise: the greater of $1,000 or 50% of the income derived","why":"IRC §6694(a) penalty is the greater of $1,000 or 50% of the income the preparer derives from the return. The $5,000 / 75% amounts apply to willful or reckless conduct under §6694(b).","steps":[],"hints":["Two tiers exist; this one is the lower tier.","Lower tier: $1,000 or 50%."],"wrong_msgs":{"Keep as written":"The amounts $500 and 25% are not the current §6694(a) amounts.","Revise: the greater of $5,000 or 75% of the income derived":"That is the willful or reckless tier, §6694(b). The statement excludes willful or reckless conduct."},"cite":"IRC §6694(a)","link":"https://www.law.cornell.edu/uscode/text/26/6694","points":1,"opts0":["Revise: the greater of $5,000 or 75% of the income derived","Revise: the greater of $1,000 or 50% of the income derived","Keep as written"]},{"id":"c6","kind":"dropdown","label":"Statement 6: standard for a disclosed position","options":["Keep as written","Revise: the preparer needs substantial authority even if the position is disclosed","Revise: the preparer needs a more-likely-than-not level of confidence"],"answer":"Keep as written","why":"For a nonshelter position, a preparer avoids the §6694(a) penalty if there is substantial authority, or the position is disclosed and has a reasonable basis.","steps":[],"hints":["Disclosure lowers the required standard.","Undisclosed: substantial authority. Disclosed: reasonable basis."],"wrong_msgs":{"Revise: the preparer needs substantial authority even if the position is disclosed":"Substantial authority is the standard for undisclosed positions.","Revise: the preparer needs a more-likely-than-not level of confidence":"That is the standard for tax shelters and reportable transactions."},"cite":"IRC §6694(a)(2)","link":"https://www.law.cornell.edu/uscode/text/26/6694","points":1,"opts0":["Revise: the preparer needs substantial authority even if the position is disclosed","Keep as written","Revise: the preparer needs a more-likely-than-not level of confidence"]}]},{"id":"REG-I-T-003","area":"I","format":"research","difficulty":2,"est_minutes":10,"testable_from":"2026-01-01","law_asof":"2026-09-29","law_note":"","cite":["IRC §6662","IRC §6501","IRC §6694","IRC §7216","31 CFR §10.29","IRC §6651"],"blueprint":{"area":"I","group":"C","topic":"Federal tax procedures: authority","task":"Research and cite authoritative sources","skill":"Application"},"params":{},"vary":{},"guards":[],"derived":[],"title":"Locate the authority: procedures and penalties","scenario":"A client asks six questions about penalties and procedures. You must identify the Internal Revenue Code section or Circular 230 section that answers each one.","task":"For each question, enter the citation of the most specific primary authority that answers it. Enter Code sections as, for example, 'IRC 6672(a)'. Enter Circular 230 sections as, for example, '31 CFR 10.29'. Include a subsection only when the question asks for it.","exhibits":[{"id":"e1","title":"Client questions","kind":"email","body":"From: client\n1. Which Code section imposes the accuracy-related penalty of 20% on an underpayment due to negligence? Give the section and subsection that states the 20% rate.\n2. Which Code section sets the general 3-year period during which the IRS may assess tax after a return is filed? (Give section and subsection.)\n3. Which Code section penalizes a return preparer for an understatement due to an unreasonable position? (Give section and subsection.)\n4. Which Code section makes it a crime, and imposes a penalty, for a preparer to disclose or use tax return information without consent, other than as allowed? (Section only.)\n5. Which Circular 230 section governs conflicts of interest for practitioners? (31 CFR section only.)\n6. Which Code section imposes the failure-to-file penalty (5% per month)? (Give section and subsection.)"}],"cells":[{"id":"c1","kind":"citation","label":"Question 1: accuracy-related penalty, 20% rate","ask":"IRC section (and subsection if asked)","accept":["6662(a)"],"partial":["6662"],"link":"https://www.law.cornell.edu/uscode/text/26/6662","why":"IRC §6662(a) imposes the 20% accuracy-related penalty; §6662(b) lists the causes, including negligence.","steps":[],"hints":["Chapter 68, subchapter A, Part II.","Section 6662, the first subsection states the rate."],"points":1},{"id":"c2","kind":"citation","label":"Question 2: general assessment period","ask":"IRC section (and subsection if asked)","accept":["6501(a)"],"partial":["6501"],"link":"https://www.law.cornell.edu/uscode/text/26/6501","why":"IRC §6501(a): tax must be assessed within 3 years after the return was filed.","steps":[],"hints":["Chapter 66, limitations.","Section 6501, subsection (a)."],"points":1},{"id":"c3","kind":"citation","label":"Question 3: preparer penalty, unreasonable position","ask":"IRC section (and subsection if asked)","accept":["6694(a)"],"partial":["6694"],"link":"https://www.law.cornell.edu/uscode/text/26/6694","why":"IRC §6694(a) penalty for understatement due to unreasonable positions; (b) is willful or reckless conduct.","steps":[],"hints":["Chapter 68, Part I subchapter B.","Section 6694, first subsection."],"points":1},{"id":"c4","kind":"citation","label":"Question 4: unauthorized disclosure or use of return information","ask":"IRC section (and subsection if asked)","accept":["7216"],"partial":[],"link":"https://www.law.cornell.edu/uscode/text/26/7216","why":"IRC §7216 criminal penalty; §6713 is the parallel civil penalty. The question asks for the criminal provision.","steps":[],"hints":["Chapter 75, crimes.","Section 7216."],"points":1},{"id":"c5","kind":"citation","label":"Question 5: conflicts of interest under Circular 230","ask":"31 CFR section","accept":["10.29"],"partial":[],"link":"https://www.law.cornell.edu/cfr/text/31/10.29","why":"31 CFR §10.29: a practitioner may not represent conflicting interests without informed written consent.","steps":[],"hints":["Subpart B of Circular 230.","Section 10.29."],"points":1},{"id":"c6","kind":"citation","label":"Question 6: failure-to-file penalty","ask":"IRC section (and subsection if asked)","accept":["6651(a)(1)"],"partial":["6651","6651(a)"],"link":"https://www.law.cornell.edu/uscode/text/26/6651","why":"IRC §6651(a)(1) failure to file; (a)(2) failure to pay; (a)(3) failure to pay after notice.","steps":[],"hints":["Chapter 68 addition to tax.","Section 6651, paragraph (1) of subsection (a)."],"points":1}]},{"id":"REG-II-T-004","area":"II","format":"dropdown_judgment","difficulty":3,"est_minutes":14,"testable_from":"2026-01-01","law_asof":"2026-09-29","law_note":"","cite":["UCC §9-324(b)","UCC §9-320(a)","UCC §9-315(a)","UCC §9-515","UCC §9-309(1)"],"blueprint":{"area":"II","group":"C","topic":"Debtor-creditor relationships: secured transactions","task":"Determine perfection and priority","skill":"Application"},"params":{},"vary":{},"guards":[],"derived":[],"title":"Secured transactions: attachment, perfection, priority","scenario":"Tomas Appliances Inc. sells refrigerators and delivery vans in State X, which has adopted UCC Article 9. Tomas has borrowed from several lenders and sells to retail customers.","task":"For each scenario in the exhibits, select the correct outcome.","exhibits":[{"id":"e1","title":"Financing history","kind":"notes","body":"Lender A (First Bank): security agreement covers all present and after-acquired inventory. Financing statement filed March 1, 2026.\nLender B (Coolco, a supplier): sold Tomas a new shipment of refrigerators on credit on June 10, 2026, and took a security interest in that shipment to secure the price."},{"id":"e2","title":"Scenarios","kind":"notes","body":"1. B filed a financing statement on June 5, and sent Lender A an authenticated notice on June 5 that it would acquire a purchase-money security interest in the refrigerators. Tomas took delivery June 10. As to the June shipment, who has priority?\n2. Alternative facts: B filed its financing statement on June 15, five days after delivery, and gave no notice to A. As to the June shipment, who has priority?\n3. Lena, a retail customer, bought a refrigerator from Tomas's showroom in the ordinary course of business. She knew that First Bank had a lien on Tomas's inventory. As to the refrigerator, does First Bank's security interest continue?\n4. First Bank also holds a perfected security interest in a delivery van (equipment). Tomas sold the van to Sam, a friend, outside the ordinary course of business. First Bank did not authorize the sale. Does the security interest continue?\n5. First Bank's financing statement was filed March 1, 2026. If no continuation statement is filed, when does perfection by that filing lapse?\n6. Nia bought a $900 washing machine for personal use from Tomas on credit. Tomas retained a purchase-money security interest in it. To perfect, must Tomas file a financing statement?"}],"cells":[{"id":"c1","kind":"dropdown","label":"Scenario 1: priority in the June shipment","options":["Lender B (Coolco)","Lender A (First Bank)","Equal; they share pro rata"],"answer":"Lender B (Coolco)","why":"A purchase-money security interest in inventory has priority over a conflicting earlier-filed interest if the PMSI holder perfects by the time the debtor receives possession and gives A authenticated notice before delivery (UCC §9-324(b)).","steps":[],"hints":["First to file is only the default rule.","PMSI super-priority in inventory requires filing plus advance notice to prior filers."],"wrong_msgs":{"Lender A (First Bank)":"A filed first, but B met the PMSI conditions (perfected and notified before delivery).","Equal; they share pro rata":"Article 9 has no pro rata sharing for competing perfected security interests."},"cite":"UCC §9-324(b)","points":1,"opts0":["Lender B (Coolco)","Equal; they share pro rata","Lender A (First Bank)"]},{"id":"c2","kind":"dropdown","label":"Scenario 2: priority in the June shipment","options":["Lender A (First Bank)","Lender B (Coolco)","Equal; they share pro rata"],"answer":"Lender A (First Bank)","why":"B did not perfect by the time Tomas took possession and gave no notice, so it loses PMSI super-priority. The default rule is first to file or perfect (§9-322(a)(1)); A filed first.","steps":[],"hints":["Was B's PMSI status preserved?","Late filing and no notice means the default first-to-file rule applies."],"wrong_msgs":{"Lender B (Coolco)":"B missed the PMSI conditions: it filed after delivery and gave no notice.","Equal; they share pro rata":"Article 9 has no pro rata sharing for competing perfected security interests."},"cite":"UCC §9-322(a)(1); §9-324(b)","points":1,"opts0":["Lender A (First Bank)","Equal; they share pro rata","Lender B (Coolco)"]},{"id":"c3","kind":"dropdown","label":"Scenario 3: sale to a buyer in ordinary course","options":["No; Lena takes free of the security interest","Yes; First Bank can repossess the refrigerator because it is perfected","Yes, because Lena knew of the lien"],"answer":"No; Lena takes free of the security interest","why":"A buyer in ordinary course takes free of a security interest created by the seller, even if perfected and even if the buyer knows it exists (UCC §9-320(a)). The bank's remedy is the sale proceeds.","steps":[],"hints":["Buyers of inventory from a merchant are protected.","The buyer's knowledge that a lien exists does not defeat the protection."],"wrong_msgs":{"Yes; First Bank can repossess the refrigerator because it is perfected":"Perfection does not defeat a buyer in ordinary course.","Yes, because Lena knew of the lien":"Knowledge of the security interest's existence is irrelevant; only knowledge that the sale violates the security agreement matters."},"cite":"UCC §9-320(a)","points":1,"opts0":["Yes, because Lena knew of the lien","Yes; First Bank can repossess the refrigerator because it is perfected","No; Lena takes free of the security interest"]},{"id":"c4","kind":"dropdown","label":"Scenario 4: sale of equipment outside the ordinary course","options":["Yes; the security interest continues in the van","No; Sam takes free because he gave value","No; the security interest is automatically terminated by any sale"],"answer":"Yes; the security interest continues in the van","why":"A security interest continues in collateral notwithstanding sale unless the secured party authorized the disposition free of the security interest (UCC §9-315(a)(1)). Sam is not a buyer in ordinary course of a merchant selling that kind of goods.","steps":[],"hints":["Continuing lien is the default rule.","Exceptions require the secured party's authorization or buyer-in-ordinary-course status."],"wrong_msgs":{"No; Sam takes free because he gave value":"Giving value is not enough. The lien continues absent authorization.","No; the security interest is automatically terminated by any sale":"Sale does not terminate the security interest without authorization."},"cite":"UCC §9-315(a)(1)","points":1,"opts0":["No; Sam takes free because he gave value","No; the security interest is automatically terminated by any sale","Yes; the security interest continues in the van"]},{"id":"c5","kind":"dropdown","label":"Scenario 5: lapse of the March 1, 2026 filing","options":["March 1, 2031","March 1, 2029","March 1, 2036"],"answer":"March 1, 2031","why":"A financing statement is effective for 5 years after filing, unless a continuation statement is filed within the six months before the fifth anniversary (UCC §9-515(a), (d)).","steps":[],"hints":["The effective period is a fixed number of years.","Five years."],"wrong_msgs":{"March 1, 2029":"That would be 3 years. The period is 5 years.","March 1, 2036":"That would be 10 years. Article 9 has no general 10-year period; 30 years applies only to public-finance and manufactured-home transactions (UCC §9-515(b))."},"cite":"UCC §9-515(a),(d)","points":1,"opts0":["March 1, 2029","March 1, 2031","March 1, 2036"]},{"id":"c6","kind":"dropdown","label":"Scenario 6: PMSI in consumer goods","options":["No; a PMSI in consumer goods is automatically perfected on attachment","Yes; filing is the only method of perfection for consumer goods","Yes; the seller must take possession of the washing machine"],"answer":"No; a PMSI in consumer goods is automatically perfected on attachment","why":"A purchase-money security interest in consumer goods is perfected automatically on attachment (UCC §9-309(1)). Filing is not required, though the buyer of consumer goods can still defeat an unfiled interest in some resales.","steps":[],"hints":["Consumer goods purchases have a special rule.","Automatic perfection for PMSI in consumer goods."],"wrong_msgs":{"Yes; filing is the only method of perfection for consumer goods":"Automatic perfection makes filing unnecessary for a PMSI in consumer goods.","Yes; the seller must take possession of the washing machine":"Possession is not required; the interest is perfected on attachment."},"cite":"UCC §9-309(1)","points":1,"opts0":["No; a PMSI in consumer goods is automatically perfected on attachment","Yes; the seller must take possession of the washing machine","Yes; filing is the only method of perfection for consumer goods"]}]},{"id":"REG-II-T-005","area":"II","format":"dropdown_judgment","difficulty":3,"est_minutes":14,"testable_from":"2026-01-01","law_asof":"2026-09-29","law_note":"","cite":["UCC §2-201(2)","UCC §2-205","UCC §2-207","UCC §2-509","UCC §2-508","UCC §2-314"],"blueprint":{"area":"II","group":"B","topic":"Contracts: sale of goods (UCC Art. 2)","task":"Apply UCC Article 2 rules","skill":"Application"},"params":{},"vary":{},"guards":[],"derived":[],"title":"Sales of goods under UCC Article 2","scenario":"Northwind Supply Co. and Baker Bikes LLC are merchants in State X, which has adopted UCC Article 2. The parties exchanged several communications about a bicycle-parts purchase.","task":"For each scenario, select the correct outcome.","exhibits":[{"id":"e1","title":"Facts and correspondence","kind":"email","body":"1. On May 2, Baker orally agreed to buy $8,000 of parts from Northwind. On May 5 Northwind mailed a signed written confirmation to Baker. Baker received it on May 8 and did not object. Baker later refused to perform. Is the contract enforceable against Baker?\n2. On June 1 Northwind gave Baker a signed writing: 'This price is good for six months.' No consideration was paid. Northwind revoked the offer on September 15. Is the revocation effective?\n3. Baker's purchase order stated terms. Northwind's acknowledgment accepted but added an arbitration clause. Baker's order limited acceptance to its terms only in a sentence that was not signed. Baker did not object. Is the arbitration clause part of the contract? (Assume both are merchants and arbitration materially alters the contract.)\n4. The contract was 'FOB Northwind's warehouse (shipment contract).' The goods were destroyed in transit after being delivered to the carrier in good condition, without fault of either party. Who bears the loss?\n5. The parts delivered were defective in a minor way; delivery time was still open (five days remained). Baker rejected them. Can Northwind cure?\n6. Ed, a neighbor who is not a merchant in lawnmowers, sold Baker his old mower for $200. Did an implied warranty of merchantability arise?"}],"cells":[{"id":"c1","kind":"dropdown","label":"Scenario 1: merchant's confirmation","options":["Yes; the merchant confirmation satisfies the statute of frauds against Baker","No; there is no signed writing by Baker","No; oral contracts for goods are never enforceable"],"answer":"Yes; the merchant confirmation satisfies the statute of frauds against Baker","why":"Between merchants, a written confirmation sent within a reasonable time satisfies the statute of frauds against the recipient unless the recipient objects in writing within 10 days of receipt (UCC §2-201(2)).","steps":[],"hints":["Merchants have a special rule.","10 days to object to a merchant confirmation."],"wrong_msgs":{"No; there is no signed writing by Baker":"The merchant's exception replaces the need for Baker's signature.","No; oral contracts for goods are never enforceable":"The statute of frauds only applies at $500 or more and has exceptions."},"cite":"UCC §2-201(2)","points":1,"opts0":["No; oral contracts for goods are never enforceable","No; there is no signed writing by Baker","Yes; the merchant confirmation satisfies the statute of frauds against Baker"]},{"id":"c2","kind":"dropdown","label":"Scenario 2: firm offer","options":["Yes; a firm offer is irrevocable only up to three months, and the three months had run","No; the offer was irrevocable for the full six months","No; a signed writing cannot be revoked until it expires"],"answer":"Yes; a firm offer is irrevocable only up to three months, and the three months had run","why":"A merchant's signed written assurance to hold an offer open is irrevocable without consideration for the stated period, but never more than three months (UCC §2-205). Northwind's offer was irrevocable until about September 1; the September 15 revocation is effective.","steps":[],"hints":["A special UCC rule replaces consideration, but it has a time cap.","Maximum irrevocability period is three months."],"wrong_msgs":{"No; the offer was irrevocable for the full six months":"Six months exceeds the statutory maximum of three.","No; a signed writing cannot be revoked until it expires":"The statute caps irrevocability at three months regardless of the stated period."},"cite":"UCC §2-205","points":1,"opts0":["Yes; a firm offer is irrevocable only up to three months, and the three months had run","No; a signed writing cannot be revoked until it expires","No; the offer was irrevocable for the full six months"]},{"id":"c3","kind":"dropdown","label":"Scenario 3: additional term (arbitration)","options":["No; a material alteration does not become part of the contract without express assent","Yes; Baker's silence is assent","Yes; additional terms always become part of the contract"],"answer":"No; a material alteration does not become part of the contract without express assent","why":"Between merchants, additional terms become part of the contract unless the offer limits acceptance, they materially alter it, or the offeror objects (UCC §2-207(2)). Arbitration is treated as a material alteration.","steps":[],"hints":["Battle of the forms.","Material alterations require express agreement."],"wrong_msgs":{"Yes; Baker's silence is assent":"Silence does not add a material term.","Yes; additional terms always become part of the contract":"Additional terms are excluded when they materially alter the contract."},"cite":"UCC §2-207(2)","points":1,"opts0":["No; a material alteration does not become part of the contract without express assent","Yes; Baker's silence is assent","Yes; additional terms always become part of the contract"]},{"id":"c4","kind":"dropdown","label":"Scenario 4: risk of loss in transit","options":["Baker (buyer)","Northwind (seller)","Shared equally"],"answer":"Baker (buyer)","why":"In a shipment contract, risk of loss passes to the buyer when the goods are duly delivered to the carrier (UCC §2-509(1)(a)).","steps":[],"hints":["Shipment contract versus destination contract.","Risk passes on delivery to the carrier."],"wrong_msgs":{"Northwind (seller)":"That would be true for a destination contract, not a shipment contract.","Shared equally":"The UCC allocates risk to one party."},"cite":"UCC §2-509(1)(a)","points":1,"opts0":["Shared equally","Baker (buyer)","Northwind (seller)"]},{"id":"c5","kind":"dropdown","label":"Scenario 5: right to cure","options":["Yes; the seller may notify the buyer and cure within the contract time","No; perfect tender means the buyer's rejection ends the contract","No; a cure is only allowed for a major defect"],"answer":"Yes; the seller may notify the buyer and cure within the contract time","why":"The buyer may reject nonconforming goods (perfect tender rule, UCC §2-601), but if the time for performance has not expired, the seller may seasonably notify the buyer of intent to cure and deliver conforming goods (UCC §2-508(1)).","steps":[],"hints":["Rejection is not the end if time remains.","Cure within the contract time."],"wrong_msgs":{"No; perfect tender means the buyer's rejection ends the contract":"The seller's right to cure within the contract time qualifies perfect tender.","No; a cure is only allowed for a major defect":"The cure right applies to any nonconformity, not only major defects."},"cite":"UCC §2-508(1)","points":1,"opts0":["Yes; the seller may notify the buyer and cure within the contract time","No; a cure is only allowed for a major defect","No; perfect tender means the buyer's rejection ends the contract"]},{"id":"c6","kind":"dropdown","label":"Scenario 6: implied warranty of merchantability","options":["No; the seller is not a merchant with respect to goods of that kind","Yes; every sale of goods carries the warranty","Yes; because the price was over $100"],"answer":"No; the seller is not a merchant with respect to goods of that kind","why":"The implied warranty of merchantability arises only when the seller is a merchant with respect to goods of that kind (UCC §2-314(1)). A casual seller is not.","steps":[],"hints":["Who makes the promise implied?","Merchant status of the seller."],"wrong_msgs":{"Yes; every sale of goods carries the warranty":"Only merchants make it.","Yes; because the price was over $100":"Price is irrelevant."},"cite":"UCC §2-314(1)","points":1,"opts0":["Yes; every sale of goods carries the warranty","No; the seller is not a merchant with respect to goods of that kind","Yes; because the price was over $100"]}]},{"id":"REG-II-T-006","area":"II","format":"document_review","difficulty":2,"est_minutes":12,"testable_from":"2026-01-01","law_asof":"2026-09-29","law_note":"","cite":["11 U.S.C. §362","11 U.S.C. §547","11 U.S.C. §727","11 U.S.C. §507","11 U.S.C. §1107","11 U.S.C. §506"],"blueprint":{"area":"II","group":"C","topic":"Debtor-creditor relationships: bankruptcy","task":"Identify bankruptcy rules","skill":"Analysis"},"params":{},"vary":{},"guards":[],"derived":[],"title":"Bankruptcy overview memo review","scenario":"You are reviewing a client memo prepared by a colleague on Chapter 7 and Chapter 11 bankruptcy concepts for a business client, Redwood Fabricators Inc.","task":"For each numbered statement, choose the option that makes the statement correct. Choose 'Keep as written' if it is already correct.","exhibits":[{"id":"e1","title":"Draft client memo","kind":"memo","body":"1. The filing of a bankruptcy petition automatically stays most collection actions against the debtor.\n2. A trustee may avoid a preferential transfer made to a creditor within 60 days before the petition was filed (or within 12 months for an insider).\n3. A debtor who receives a Chapter 7 discharge may not receive another Chapter 7 discharge in a case commenced within 4 years of the earlier case.\n4. In distribution of estate assets, general unsecured creditors are paid before administrative expenses of the estate.\n5. In a Chapter 11 case, a trustee must always be appointed to run the debtor's business.\n6. If collateral sells for less than the secured debt, the secured creditor holds a general unsecured claim for the deficiency."}],"cells":[{"id":"c1","kind":"dropdown","label":"Statement 1: automatic stay","options":["Keep as written","Revise: the stay arises only after the court holds a hearing","Revise: the stay applies only to secured creditors"],"answer":"Keep as written","why":"The filing of a petition operates as an automatic stay of most collection activity (11 U.S.C. §362(a)) without a court order.","steps":[],"hints":["Effective immediately on filing.","No hearing is needed."],"wrong_msgs":{"Revise: the stay arises only after the court holds a hearing":"The stay is automatic upon filing.","Revise: the stay applies only to secured creditors":"It applies to most creditors."},"cite":"11 U.S.C. §362(a)","points":1,"opts0":["Revise: the stay arises only after the court holds a hearing","Keep as written","Revise: the stay applies only to secured creditors"]},{"id":"c2","kind":"dropdown","label":"Statement 2: preference period","options":["Keep as written","Revise: 90 days (or 1 year for an insider)","Revise: 6 months (or 2 years for an insider)"],"answer":"Revise: 90 days (or 1 year for an insider)","why":"A preferential transfer within 90 days before the petition (one year for insiders) may be avoided (11 U.S.C. §547(b)(4)).","steps":[],"hints":["The period is roughly one quarter.","90 days and one year."],"wrong_msgs":{"Keep as written":"60 days is not the period; it is 90 days.","Revise: 6 months (or 2 years for an insider)":"Periods are 90 days and 1 year."},"cite":"11 U.S.C. §547(b)","points":1,"opts0":["Revise: 6 months (or 2 years for an insider)","Keep as written","Revise: 90 days (or 1 year for an insider)"]},{"id":"c3","kind":"dropdown","label":"Statement 3: repeat Chapter 7 discharge","options":["Keep as written","Revise: 8 years","Revise: 2 years"],"answer":"Revise: 8 years","why":"A Chapter 7 discharge is not granted if the debtor received a Chapter 7 discharge in a case commenced within 8 years before the current petition (11 U.S.C. §727(a)(8)).","steps":[],"hints":["The waiting period is longer than the statement says.","8 years between filing dates."],"wrong_msgs":{"Keep as written":"4 years applies to other combinations (e.g., Chapter 7 then Chapter 13 discharge); Chapter 7 to Chapter 7 is 8 years.","Revise: 2 years":"Too short."},"cite":"11 U.S.C. §727(a)(8)","points":1,"opts0":["Keep as written","Revise: 2 years","Revise: 8 years"]},{"id":"c4","kind":"dropdown","label":"Statement 4: order of payment","options":["Keep as written","Revise: administrative expenses are paid before general unsecured creditors","Revise: general unsecured creditors are paid before secured creditors"],"answer":"Revise: administrative expenses are paid before general unsecured creditors","why":"Administrative expenses of the estate have priority over general unsecured claims (11 U.S.C. §507(a)(2)); secured creditors are paid from their collateral first.","steps":[],"hints":["Priority ranks costs of running the estate ahead of ordinary claims.","Unsecured general claims are near the end."],"wrong_msgs":{"Keep as written":"General unsecured claims rank after priority claims such as administrative expenses.","Revise: general unsecured creditors are paid before secured creditors":"Secured creditors are paid from their collateral first."},"cite":"11 U.S.C. §507(a)(2)","points":1,"opts0":["Keep as written","Revise: general unsecured creditors are paid before secured creditors","Revise: administrative expenses are paid before general unsecured creditors"]},{"id":"c5","kind":"dropdown","label":"Statement 5: Chapter 11 management","options":["Keep as written","Revise: the debtor usually remains a debtor in possession unless a trustee is appointed for cause","Revise: creditors elect a trustee automatically"],"answer":"Revise: the debtor usually remains a debtor in possession unless a trustee is appointed for cause","why":"In Chapter 11 the debtor ordinarily continues as debtor in possession (11 U.S.C. §1107); a trustee is appointed only for cause such as fraud or gross mismanagement (§1104(a)).","steps":[],"hints":["Chapter 11 aims to reorganize, not liquidate.","Debtor in possession."],"wrong_msgs":{"Keep as written":"A trustee is the exception, not the rule.","Revise: creditors elect a trustee automatically":"Creditors do not automatically elect a trustee."},"cite":"11 U.S.C. §1107, §1104(a)","points":1,"opts0":["Revise: the debtor usually remains a debtor in possession unless a trustee is appointed for cause","Revise: creditors elect a trustee automatically","Keep as written"]},{"id":"c6","kind":"dropdown","label":"Statement 6: deficiency after collateral sale","options":["Keep as written","Revise: the secured creditor loses the deficiency entirely","Revise: the deficiency is a priority claim"],"answer":"Keep as written","why":"A secured claim is secured only to the extent of the collateral's value; the shortfall is an unsecured claim (11 U.S.C. §506(a)(1)).","steps":[],"hints":["Secured to the extent of value.","The remainder is unsecured."],"wrong_msgs":{"Revise: the secured creditor loses the deficiency entirely":"The creditor still has an unsecured claim.","Revise: the deficiency is a priority claim":"A deficiency is a general unsecured claim."},"cite":"11 U.S.C. §506(a)(1)","points":1,"opts0":["Revise: the secured creditor loses the deficiency entirely","Revise: the deficiency is a priority claim","Keep as written"]}]},{"id":"REG-III-T-007","area":"III","format":"numeric_table","difficulty":2,"est_minutes":12,"testable_from":"2026-01-01","law_asof":"2026-09-29","law_note":"","cite":["IRC §1015(a)","IRC §1015(d)(6)","IRC §1014(a)"],"blueprint":{"area":"III","group":"A","topic":"Basis of assets","task":"Determine basis of gifted and inherited property and gain or loss on disposition","skill":"Application"},"params":{"A_db":42000,"A_fmv":30000,"A_p1":36000,"A_p2":25000,"B_db":20000,"B_fmv":50000,"gtax":4500,"B_gift":50000,"B_p":60000,"C_fmv":90000,"C_p":97000},"vary":{"A_db":[40000,42000,45000],"A_p1":[34000,36000,38000],"A_p2":[22000,25000,27000],"gtax":[3000,4500,6000],"B_p":[58000,60000,65000],"C_p":[93000,97000,101000]},"guards":["A_fmv < A_p1 < A_db","A_p2 < A_fmv","B_p > c5_guard"],"derived":[["c5_guard","B_db+gtax"]],"title":"Basis and gain or loss on gifted and inherited property","scenario":"Elena Cruz received three blocks of stock in 2026 and sold each one during the year. She has no other transactions. Enter a loss as a negative number.","task":"Using the exhibit, compute Elena's basis and recognized gain or (loss) for each block. Round to the nearest dollar.","exhibits":[{"id":"e1","title":"Acquisition and sale data","kind":"table","body":[["Item","Amount"],["Lot A (gift from her aunt, no gift tax paid): aunt's adjusted basis","${A_db:,}"],["Lot A: fair market value on the date of gift","${A_fmv:,}"],["Lot A: sale price in Sale 1","${A_p1:,}"],["Lot A: alternative sale price in Sale 2","${A_p2:,}"],["Lot B (gift from her uncle): uncle's adjusted basis","${B_db:,}"],["Lot B: fair market value on the date of gift","${B_fmv:,}"],["Lot B: gift tax the uncle paid on the gift","${gtax:,}"],["Lot B: amount of the gift for gift tax purposes (his annual exclusion was already used)","${B_gift:,}"],["Lot B: sale price","${B_p:,}"],["Lot C (inherited from her father): fair market value at date of death","${C_fmv:,}"],["Lot C: sale price","${C_p:,}"]]},{"id":"e2","title":"Note","kind":"notes","body":"Treat Sale 1 and Sale 2 as alternative facts for Lot A (Elena sold Lot A only once). No alternate valuation date was elected for Lot C."}],"cells":[{"id":"c1","kind":"number","label":"Lot A: basis used to compute a gain","expr":"A_db","fmt":"$","tol":1,"why":"Gifted property with FMV below the donor's basis has a dual basis. To compute a gain, the carryover (donor's) basis of ${A_db:,} is used.","steps":["FMV at gift ${A_fmv:,} < donor basis ${A_db:,}: dual basis","Gain basis = donor's basis"],"hints":["Look at FMV versus the donor's basis.","Depreciated gift property: donor basis for gains, FMV for losses."],"traps":[{"expr":"A_fmv","msg":"You used the FMV at the date of gift. That is the loss basis."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1015","points":1},{"id":"c2","kind":"number","label":"Lot A: basis used to compute a loss","expr":"A_fmv","fmt":"$","tol":1,"why":"The loss basis is the lower of donor basis or FMV at the gift date, here ${A_fmv:,} (IRC §1015(a)).","steps":["Loss basis = lesser of donor basis and FMV = ${A_fmv:,}"],"hints":["Which of the two numbers is lower?","FMV at gift date."],"traps":[{"expr":"A_db","msg":"You used the gain basis. When FMV at the gift date is lower, a loss is measured from FMV."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1015","points":1},{"id":"c3","kind":"number","label":"Lot A, Sale 1: recognized gain or (loss)","expr":"dual_basis(A_p1, c1, c2)","fmt":"$","tol":0,"why":"Sale 1 price ${A_p1:,} is between the loss basis ${A_fmv:,} and the gain basis ${A_db:,}, so there is neither gain nor loss.","steps":["Price above loss basis and below gain basis","Gain = 0 and loss = 0"],"hints":["Test the price against both bases.","Between the two bases means zero."],"traps":[{"expr":"A_p1-A_db","msg":"You used only the donor's basis, which shows a loss. The dual-basis rule gives zero when the price falls between the two bases."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1015","points":1},{"id":"c4","kind":"number","label":"Lot A, Sale 2: recognized gain or (loss)","expr":"dual_basis(A_p2, c1, c2)","fmt":"$","tol":1,"why":"Sale 2 price ${A_p2:,} is below the loss basis ${A_fmv:,}: loss = ${A_p2:,} - ${A_fmv:,}.","steps":["Loss = price - loss basis","${A_p2:,} - ${A_fmv:,} = ${c4:,}"],"hints":["Which basis applies when the price is below FMV at the gift date?","Price minus FMV at gift date."],"traps":[{"expr":"A_p2-A_db","msg":"You used the donor's basis for the loss. A loss uses the lower FMV."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1015","points":1},{"id":"c5","kind":"number","label":"Lot B: adjusted basis after the gift-tax adjustment","expr":"B_db+gtax*(B_fmv-B_db)/B_gift","fmt":"$","tol":1,"why":"The donee's basis increases by the part of the gift tax paid attributable to net appreciation: gift tax x (FMV - donor basis) / amount of gift (IRC §1015(d)(6)).","steps":["Net appreciation = ${B_fmv:,} - ${B_db:,}","Increase = ${gtax:,} x net appreciation / ${B_gift:,}","Basis = ${B_db:,} + increase = ${c5:,}"],"hints":["Only part of the gift tax is added to basis.","Increase = gift tax x net appreciation / amount of gift."],"traps":[{"expr":"B_db+gtax","msg":"You added the entire gift tax. Only the portion attributable to net appreciation is added."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1015","points":1},{"id":"c6","kind":"number","label":"Lot B: recognized gain","expr":"B_p-c5","fmt":"$","tol":1,"why":"Gain = price - adjusted basis. The price is above the gain basis.","steps":["${B_p:,} - ${c5:,} = ${c6:,}"],"hints":["Price less the basis from the previous cell.","Use the gift-tax-adjusted basis."],"traps":[{"expr":"B_p-B_db","msg":"You ignored the gift-tax adjustment to basis."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1015","points":1},{"id":"c7","kind":"number","label":"Lot C: recognized gain","expr":"C_p-C_fmv","fmt":"$","tol":1,"why":"Inherited property takes a basis equal to FMV at death (IRC §1014(a)), so gain = ${C_p:,} - ${C_fmv:,}.","steps":["Basis = FMV at date of death = ${C_fmv:,}","Gain = ${c7:,}"],"hints":["Basis of inherited property is stepped up (or down).","FMV at the date of death."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1014","points":1}]},{"id":"REG-III-T-008","area":"III","format":"numeric_table","difficulty":3,"est_minutes":14,"testable_from":"2026-01-01","law_asof":"2026-09-29","law_note":"","cite":["IRC §1031(a)","IRC §1031(b)","IRC §1031(d)","Reg. §1.1031(d)-2"],"blueprint":{"area":"III","group":"B","topic":"Like-kind exchanges","task":"Compute recognized gain and basis in a like-kind exchange","skill":"Application"},"params":{"fmv_old":600000,"adj":350000,"mort_old":100000,"fmv_new":520000,"mort_new":60000},"vary":{"fmv_new":[500000,520000,540000],"mort_new":[40000,60000,80000],"adj":[300000,350000,380000]},"guards":["cash >= 10000","g_c2 > g_c3","g_c3 > 0"],"derived":[["cash","(fmv_old-mort_old)-(fmv_new-mort_new)"],["s1","fmv_new+cash"],["nr","max(0, mort_old-mort_new)"],["g_c1","fmv_new+cash+mort_old-mort_new"],["g_c2","g_c1-adj"],["g_c3","cash+max(0,mort_old-mort_new)"]],"title":"Like-kind exchange of real property with boot and liabilities","scenario":"Marlow Holdings Inc., a C corporation, exchanged an office building held for investment for a different investment office building in a qualifying deferred exchange in 2026. The replacement property was identified and acquired within the required time limits.","task":"Using the exhibit, compute the tax results of the exchange. Round to the nearest dollar.","exhibits":[{"id":"e1","title":"Exchange data","kind":"table","body":[["Item","Amount"],["Relinquished building: fair market value","${fmv_old:,}"],["Relinquished building: adjusted basis","${adj:,}"],["Mortgage on relinquished building, assumed by the other party","${mort_old:,}"],["Replacement building: fair market value","${fmv_new:,}"],["Mortgage on replacement building, assumed by Marlow","${mort_new:,}"],["Cash received by Marlow","${cash:,}"]]}],"cells":[{"id":"c1","kind":"number","label":"Amount realized","expr":"fmv_new+cash+mort_old-mort_new","fmt":"$","tol":1,"why":"Amount realized = FMV of property received + cash + liabilities relieved - liabilities assumed = ${fmv_new:,} + ${cash:,} + ${mort_old:,} - ${mort_new:,}.","steps":["${fmv_new:,} + ${cash:,} = ${s1:,}","+ ${mort_old:,} - ${mort_new:,} = ${c1:,}"],"hints":["Include the mortgage relief and the mortgage assumed.","Liabilities assumed by Marlow offset liabilities relieved."],"traps":[{"expr":"fmv_new+cash","msg":"You left out the net liability relief."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1031","points":1},{"id":"c2","kind":"number","label":"Realized gain","expr":"c1-adj","fmt":"$","tol":1,"why":"Realized gain = amount realized - adjusted basis.","steps":["${c1:,} - ${adj:,} = ${c2:,}"],"hints":["Amount realized less adjusted basis.","Use the previous cell."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1031","points":1},{"id":"c3","kind":"number","label":"Boot received (cash plus net liability relief)","expr":"cash+max(0, mort_old-mort_new)","fmt":"$","tol":1,"why":"Boot = cash ${cash:,} + net mortgage relief (${mort_old:,} - ${mort_new:,}). Liabilities assumed offset liabilities relieved.","steps":["Net relief = ${mort_old:,} - ${mort_new:,} = ${nr:,}","Boot = ${cash:,} + ${nr:,} = ${c3:,}"],"hints":["Boot includes debt relief that is not offset by debt assumed.","Cash plus net liability relief."],"traps":[{"expr":"cash","msg":"You counted cash only. Net relief from the mortgage is also boot."},{"expr":"cash+mort_old","msg":"You did not offset the mortgage assumed on the replacement building."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1031","points":1},{"id":"c4","kind":"number","label":"Recognized gain","expr":"min(c2,c3)","fmt":"$","tol":1,"why":"Recognized gain = lesser of realized gain or boot received (IRC §1031(b)).","steps":["min(${c2:,}, ${c3:,}) = ${c4:,}"],"hints":["It is limited by both numbers.","Lesser of realized gain and boot."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1031","points":1},{"id":"c5","kind":"number","label":"Deferred gain","expr":"c2-c4","fmt":"$","tol":1,"why":"Deferred gain = realized gain - recognized gain.","steps":["${c2:,} - ${c4:,} = ${c5:,}"],"hints":["What part of the realized gain is not taxed now?","Realized less recognized."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1031","points":1},{"id":"c6","kind":"number","label":"Basis of the replacement building","expr":"fmv_new-c5","fmt":"$","tol":1,"why":"Basis of the replacement property = FMV - deferred gain. Check: old basis ${adj:,} - cash ${cash:,} + gain recognized ${c4:,} - liabilities relieved ${mort_old:,} + liabilities assumed ${mort_new:,}.","steps":["${fmv_new:,} - ${c5:,} = ${c6:,}","Cross-check using the carryover formula gives the same amount"],"hints":["Basis keeps the deferred gain alive.","FMV of the new property less deferred gain."],"traps":[{"expr":"fmv_new","msg":"You used FMV, which would eliminate the deferred gain."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1031","points":1}]},{"id":"REG-III-T-009","area":"III","format":"document_review","difficulty":2,"est_minutes":12,"testable_from":"2026-01-01","law_asof":"2026-09-29","law_note":"","cite":["IRC §1245","IRC §1250","IRC §1231(c)","IRC §1223(9)","IRC §267"],"blueprint":{"area":"III","group":"C","topic":"Character of gain and loss","task":"Identify recapture, holding period, and related-party rules","skill":"Analysis"},"params":{},"vary":{},"guards":[],"derived":[],"title":"Character of gain and loss: review of a client memo","scenario":"You are reviewing a draft memo to Harlan Reid, an individual who sold several assets in 2026.","task":"For each numbered statement, choose the option that makes the statement correct. Choose 'Keep as written' if it is already correct.","exhibits":[{"id":"e1","title":"Draft memo to client","kind":"memo","body":"1. Your gain on the sale of the used machinery, to the extent of depreciation you claimed, is unrecaptured section 1250 gain taxed at a maximum 25% rate.\n2. Your gain on the sale of the office building, depreciated straight line, that is attributable to depreciation taken is unrecaptured section 1250 gain, taxed at a maximum rate of 25%, and there is no ordinary income recapture under section 1250 for straight-line depreciation.\n3. Your net section 1231 gain for 2026 is treated as ordinary income to the extent of nonrecaptured net section 1231 losses from the previous 3 years.\n4. The land you held for investment and sold after 9 months at a gain is a long-term capital gain.\n5. The stock you inherited from your mother and sold six months after her death produces a long-term capital gain or loss, regardless of how long you held it.\n6. The loss on your sale of a building to a corporation you own 60% by value is a deductible capital loss in 2026."}],"cells":[{"id":"c1","kind":"dropdown","label":"Statement 1: machinery gain","options":["Keep as written","Revise: the gain up to depreciation taken is ordinary income under section 1245","Revise: the entire gain is section 1231 gain taxed at 0%, 15%, or 20%"],"answer":"Revise: the gain up to depreciation taken is ordinary income under section 1245","why":"Personal property (machinery) is section 1245 property: gain up to prior depreciation is recaptured as ordinary income. Unrecaptured section 1250 gain applies only to real property.","steps":[],"hints":["Machinery is personal property.","Section 1245 recaptures all depreciation as ordinary income."],"wrong_msgs":{"Keep as written":"Unrecaptured §1250 gain applies to depreciable real property, not machinery.","Revise: the entire gain is section 1231 gain taxed at 0%, 15%, or 20%":"§1245 recapture is ordinary income to the extent of depreciation before §1231 treatment."},"cite":"IRC §1245(a)","link":"https://www.law.cornell.edu/uscode/text/26/1245","points":1,"opts0":["Revise: the entire gain is section 1231 gain taxed at 0%, 15%, or 20%","Revise: the gain up to depreciation taken is ordinary income under section 1245","Keep as written"]},{"id":"c2","kind":"dropdown","label":"Statement 2: office building, straight-line depreciation","options":["Keep as written","Revise: the gain attributable to depreciation is ordinary income under section 1250","Revise: the gain is taxed at a maximum 20% with no special rate"],"answer":"Keep as written","why":"Gain on depreciable real property attributable to straight-line depreciation is unrecaptured §1250 gain (max 25% for individuals) and there is no ordinary recapture under §1250 because only excess (accelerated) depreciation is recaptured.","steps":[],"hints":["Straight-line versus accelerated.","Ordinary recapture under §1250 covers only additional depreciation."],"wrong_msgs":{"Revise: the gain attributable to depreciation is ordinary income under section 1250":"Only additional depreciation over straight line is ordinary income under §1250.","Revise: the gain is taxed at a maximum 20% with no special rate":"The portion attributable to depreciation is taxed at up to 25%."},"cite":"IRC §1(h)(6); §1250","link":"https://www.law.cornell.edu/uscode/text/26/1250","points":1,"opts0":["Keep as written","Revise: the gain is taxed at a maximum 20% with no special rate","Revise: the gain attributable to depreciation is ordinary income under section 1250"]},{"id":"c3","kind":"dropdown","label":"Statement 3: section 1231 look-back","options":["Keep as written","Revise: 5 years","Revise: 10 years"],"answer":"Revise: 5 years","why":"Net §1231 gain is recharacterized as ordinary income to the extent of nonrecaptured net §1231 losses of the five preceding years (IRC §1231(c)).","steps":[],"hints":["The look-back is longer than three years.","Five years."],"wrong_msgs":{"Keep as written":"The look-back is 5 years.","Revise: 10 years":"The look-back is 5 years, not 10."},"cite":"IRC §1231(c)","link":"https://www.law.cornell.edu/uscode/text/26/1231","points":1,"opts0":["Revise: 10 years","Keep as written","Revise: 5 years"]},{"id":"c4","kind":"dropdown","label":"Statement 4: holding period of land","options":["Keep as written","Revise: it is a short-term capital gain because the holding period was one year or less","Revise: it is a section 1231 gain"],"answer":"Revise: it is a short-term capital gain because the holding period was one year or less","why":"Long-term treatment requires holding the asset more than one year. Land held for investment for 9 months produces a short-term gain, taxed at ordinary rates.","steps":[],"hints":["Count the holding period.","More than one year is required."],"wrong_msgs":{"Keep as written":"Nine months is not more than a year.","Revise: it is a section 1231 gain":"§1231 requires a holding period of more than one year for property used in a business."},"cite":"IRC §1222","link":"https://www.law.cornell.edu/uscode/text/26/1222","points":1,"opts0":["Revise: it is a short-term capital gain because the holding period was one year or less","Revise: it is a section 1231 gain","Keep as written"]},{"id":"c5","kind":"dropdown","label":"Statement 5: inherited stock","options":["Keep as written","Revise: it is short-term because the holding period was under one year","Revise: it is long-term only if held over one year after death"],"answer":"Keep as written","why":"Property acquired from a decedent is treated as held more than one year (IRC §1223(9)), whenever it is sold.","steps":[],"hints":["Special rule for inherited property.","Automatic long-term treatment."],"wrong_msgs":{"Revise: it is short-term because the holding period was under one year":"Inherited property gets automatic long-term treatment.","Revise: it is long-term only if held over one year after death":"The one-year test does not apply to inherited property."},"cite":"IRC §1223(9)","link":"https://www.law.cornell.edu/uscode/text/26/1223","points":1,"opts0":["Keep as written","Revise: it is long-term only if held over one year after death","Revise: it is short-term because the holding period was under one year"]},{"id":"c6","kind":"dropdown","label":"Statement 6: sale to a controlled corporation","options":["Keep as written","Revise: the loss is disallowed because the buyer is a related person","Revise: the loss is deductible but only as an ordinary loss"],"answer":"Revise: the loss is disallowed because the buyer is a related person","why":"A loss on a sale between a taxpayer and a corporation owned more than 50% by the taxpayer is disallowed (IRC §267(a)(1), (b)(2)). The buyer may use the disallowed loss to reduce gain on its later sale (§267(d)).","steps":[],"hints":["Ownership above 50% makes them related persons.","Loss disallowed."],"wrong_msgs":{"Keep as written":"Loss on related-party sales is disallowed.","Revise: the loss is deductible but only as an ordinary loss":"Character is irrelevant when the loss is disallowed."},"cite":"IRC §267(a)(1), (b)(2)","link":"https://www.law.cornell.edu/uscode/text/26/267","points":1,"opts0":["Revise: the loss is deductible but only as an ordinary loss","Keep as written","Revise: the loss is disallowed because the buyer is a related person"]}]},{"id":"REG-III-T-010","area":"III","format":"research","difficulty":2,"est_minutes":10,"testable_from":"2026-01-01","law_asof":"2026-09-29","law_note":"","cite":["IRC §121","IRC §1014","IRC §1091","IRC §267","IRC §1031","IRC §453"],"blueprint":{"area":"III","group":"A","topic":"Research: property transactions","task":"Research and cite authority for property transactions","skill":"Application"},"params":{},"vary":{},"guards":[],"derived":[],"title":"Locate the authority: property transactions","scenario":"A client's controller asks six questions about the tax treatment of property transactions. Identify the primary authority that answers each one.","task":"For each question, enter the Internal Revenue Code citation (for example, 'IRC 1223(9)'). Provide the subsection or paragraph only when the question asks for it.","exhibits":[{"id":"e1","title":"Questions","kind":"email","body":"1. Which section allows an individual to exclude gain on the sale of a principal residence? (Section only.)\n2. Which section and subsection give the general rule for the basis of property acquired from a decedent?\n3. Which section and subsection disallow a loss on a wash sale of stock?\n4. Which section, subsection, and paragraph disallow a loss on a sale between related persons?\n5. Which section and subsection provide that no gain or loss is recognized on an exchange of real property held for productive use in a trade or business or for investment?\n6. Which section and subsection state that income from an installment sale is taken into account under the installment method?"}],"cells":[{"id":"c1","kind":"citation","label":"Question 1: exclusion of gain on the sale of a principal residence","ask":"IRC section (and subsection if asked)","accept":["121","121(a)"],"partial":[],"link":"https://www.law.cornell.edu/uscode/text/26/121","why":"IRC §121(a) excludes up to $250,000 ($500,000 joint) of gain if ownership and use tests are met.","steps":[],"hints":["Part III of subchapter B.","Section 121."],"points":1},{"id":"c2","kind":"citation","label":"Question 2: basis of property acquired from a decedent","ask":"IRC section (and subsection if asked)","accept":["1014(a)","1014(a)(1)"],"partial":["1014"],"link":"https://www.law.cornell.edu/uscode/text/26/1014","why":"IRC §1014(a)(1): basis is the FMV at the decedent's death (or alternate valuation date).","steps":[],"hints":["Section 1014, first subsection.","Subsection (a)."],"points":1},{"id":"c3","kind":"citation","label":"Question 3: wash sale loss disallowance","ask":"IRC section (and subsection if asked)","accept":["1091(a)"],"partial":["1091"],"link":"https://www.law.cornell.edu/uscode/text/26/1091","why":"IRC §1091(a) disallows the loss if substantially identical stock is acquired within 30 days before or after the sale.","steps":[],"hints":["Section 1091.","Subsection (a) states the rule."],"points":1},{"id":"c4","kind":"citation","label":"Question 4: related-party loss disallowance","ask":"IRC section (and subsection if asked)","accept":["267(a)(1)"],"partial":["267","267(a)"],"link":"https://www.law.cornell.edu/uscode/text/26/267","why":"IRC §267(a)(1) disallows losses on sales or exchanges between persons specified in subsection (b).","steps":[],"hints":["Section 267, subsection (a).","Paragraph (1)."],"points":1},{"id":"c5","kind":"citation","label":"Question 5: nonrecognition on like-kind exchanges","ask":"IRC section (and subsection if asked)","accept":["1031(a)(1)","1031(a)"],"partial":["1031"],"link":"https://www.law.cornell.edu/uscode/text/26/1031","why":"IRC §1031(a)(1) applies to real property held for productive use in trade or business or for investment (personal property is excluded after 2017).","steps":[],"hints":["Section 1031.","Subsection (a), paragraph (1)."],"points":1},{"id":"c6","kind":"citation","label":"Question 6: installment method","ask":"IRC section (and subsection if asked)","accept":["453(a)"],"partial":["453"],"link":"https://www.law.cornell.edu/uscode/text/26/453","why":"IRC §453(a) requires the installment method for installment sales unless the taxpayer elects out under §453(d).","steps":[],"hints":["Section 453.","Subsection (a)."],"points":1}]},{"id":"REG-III-T-011","area":"III","format":"dropdown_judgment","difficulty":2,"est_minutes":10,"testable_from":"2026-07-01","law_asof":"2026-09-29","law_note":"OBBBA (P.L. 119-21) §70301 restores 100% bonus for property acquired after 2025-01-19; testable from 2026-07-01 (AICPA six-month rule).","cite":["IRC §168(c)","IRC §168(e)","IRC §168(k)","Notice 2026-11"],"blueprint":{"area":"III","group":"D","topic":"Cost recovery","task":"Determine MACRS recovery periods and bonus depreciation","skill":"Application"},"params":{},"vary":{},"guards":[],"derived":[],"title":"Cost recovery: recovery periods and bonus depreciation","scenario":"Juniper Properties LLC is a calendar-year business that placed several assets into service in 2026. All assets were acquired new, after January 19, 2025, for business or rental use in the United States.","task":"For each asset, select the MACRS recovery period. For the last item, select the bonus depreciation percentage.","exhibits":[{"id":"e1","title":"Assets placed in service","kind":"table","body":[["Asset","Use"],["Computer equipment","Office"],["Office furniture","Office"],["Apartment building (residential rental)","Rental"],["Warehouse building (nonresidential)","Used in business"],["Land under the warehouse","Used in business"],["Paved parking lot and fencing (land improvements)","Used in business"],["New machinery acquired February 3, 2026, placed in service February 2026","Used in business"]]},{"id":"e2","title":"Law note","kind":"statute_note","body":"Public Law 119-21 (2025) made 100% bonus depreciation under section 168(k) permanent for qualified property acquired after January 19, 2025. Treat this law as effective for the 2026 exam window starting July 1, 2026."}],"cells":[{"id":"c1","kind":"dropdown","label":"Recovery period: computer equipment","options":["3-year","5-year","7-year","15-year","27.5-year","39-year","Not depreciable"],"answer":"5-year","why":"Computers and peripheral equipment are 5-year property (IRC §168(e)(3)(B)).","steps":[],"hints":["Computers are listed by name in the Code.","Five years."],"wrong_msgs":{"3-year":"3-year property covers items such as certain tractor units and racehorses, not this asset. The correct answer is 5-year.","7-year":"7-year property is the default class for furniture, fixtures, and most machinery. The correct answer is 5-year.","15-year":"15-year property covers land improvements such as paving and fencing. The correct answer is 5-year.","27.5-year":"27.5 years applies only to residential rental real property. The correct answer is 5-year.","39-year":"39 years applies to nonresidential real property (the building, not the land). The correct answer is 5-year.","Not depreciable":"Only land and other property with no determinable life is not depreciable. The correct answer is 5-year."},"link":"https://www.law.cornell.edu/uscode/text/26/168","points":1,"opts0":["3-year","15-year","39-year","Not depreciable","7-year","27.5-year","5-year"]},{"id":"c2","kind":"dropdown","label":"Recovery period: office furniture","options":["3-year","5-year","7-year","15-year","27.5-year","39-year","Not depreciable"],"answer":"7-year","why":"Office furniture and fixtures are 7-year property (Rev. Proc. 87-56 asset class 00.11).","steps":[],"hints":["Default class for property with no class life.","Seven years."],"wrong_msgs":{"3-year":"3-year property covers items such as certain tractor units and racehorses, not this asset. The correct answer is 7-year.","5-year":"5-year property covers items such as cars, light trucks, and computers. The correct answer is 7-year.","15-year":"15-year property covers land improvements such as paving and fencing. The correct answer is 7-year.","27.5-year":"27.5 years applies only to residential rental real property. The correct answer is 7-year.","39-year":"39 years applies to nonresidential real property (the building, not the land). The correct answer is 7-year.","Not depreciable":"Only land and other property with no determinable life is not depreciable. The correct answer is 7-year."},"link":"https://www.law.cornell.edu/uscode/text/26/168","points":1,"opts0":["5-year","39-year","3-year","15-year","7-year","27.5-year","Not depreciable"]},{"id":"c3","kind":"dropdown","label":"Recovery period: apartment building","options":["3-year","5-year","7-year","15-year","27.5-year","39-year","Not depreciable"],"answer":"27.5-year","why":"Residential rental property is depreciated straight line over 27.5 years (IRC §168(c)).","steps":[],"hints":["Residential rental, mid-month convention.","27.5 years."],"wrong_msgs":{"3-year":"3-year property covers items such as certain tractor units and racehorses, not this asset. The correct answer is 27.5-year.","5-year":"5-year property covers items such as cars, light trucks, and computers. The correct answer is 27.5-year.","7-year":"7-year property is the default class for furniture, fixtures, and most machinery. The correct answer is 27.5-year.","15-year":"15-year property covers land improvements such as paving and fencing. The correct answer is 27.5-year.","39-year":"39 years applies to nonresidential real property (the building, not the land). The correct answer is 27.5-year.","Not depreciable":"Only land and other property with no determinable life is not depreciable. The correct answer is 27.5-year."},"link":"https://www.law.cornell.edu/uscode/text/26/168","points":1,"opts0":["15-year","5-year","39-year","3-year","7-year","Not depreciable","27.5-year"]},{"id":"c4","kind":"dropdown","label":"Recovery period: warehouse building","options":["3-year","5-year","7-year","15-year","27.5-year","39-year","Not depreciable"],"answer":"39-year","why":"Nonresidential real property is depreciated straight line over 39 years (IRC §168(c)).","steps":[],"hints":["Not residential.","39 years."],"wrong_msgs":{"3-year":"3-year property covers items such as certain tractor units and racehorses, not this asset. The correct answer is 39-year.","5-year":"5-year property covers items such as cars, light trucks, and computers. The correct answer is 39-year.","7-year":"7-year property is the default class for furniture, fixtures, and most machinery. The correct answer is 39-year.","15-year":"15-year property covers land improvements such as paving and fencing. The correct answer is 39-year.","27.5-year":"27.5 years applies only to residential rental real property. The correct answer is 39-year.","Not depreciable":"Only land and other property with no determinable life is not depreciable. The correct answer is 39-year."},"link":"https://www.law.cornell.edu/uscode/text/26/168","points":1,"opts0":["3-year","Not depreciable","15-year","39-year","27.5-year","7-year","5-year"]},{"id":"c5","kind":"dropdown","label":"Recovery period: land under the warehouse","options":["3-year","5-year","7-year","15-year","27.5-year","39-year","Not depreciable"],"answer":"Not depreciable","why":"Land is not depreciable; it has no determinable useful life (Reg. §1.167(a)-2).","steps":[],"hints":["Does land wear out?","No cost recovery."],"wrong_msgs":{"3-year":"3-year property covers items such as certain tractor units and racehorses, not this asset. The correct answer is Not depreciable.","5-year":"5-year property covers items such as cars, light trucks, and computers. The correct answer is Not depreciable.","7-year":"7-year property is the default class for furniture, fixtures, and most machinery. The correct answer is Not depreciable.","15-year":"15-year property covers land improvements such as paving and fencing. The correct answer is Not depreciable.","27.5-year":"27.5 years applies only to residential rental real property. The correct answer is Not depreciable.","39-year":"39 years applies to nonresidential real property (the building, not the land). The correct answer is Not depreciable."},"link":"https://www.law.cornell.edu/uscode/text/26/167","points":1,"opts0":["39-year","7-year","5-year","Not depreciable","15-year","27.5-year","3-year"]},{"id":"c6","kind":"dropdown","label":"Recovery period: parking lot and fencing","options":["3-year","5-year","7-year","15-year","27.5-year","39-year","Not depreciable"],"answer":"15-year","why":"Land improvements such as sidewalks, roads, fences, and parking lots are 15-year property (asset class 00.3).","steps":[],"hints":["Improvements to land are not land.","15-year property, 150% declining balance."],"wrong_msgs":{"3-year":"3-year property covers items such as certain tractor units and racehorses, not this asset. The correct answer is 15-year.","5-year":"5-year property covers items such as cars, light trucks, and computers. The correct answer is 15-year.","7-year":"7-year property is the default class for furniture, fixtures, and most machinery. The correct answer is 15-year.","27.5-year":"27.5 years applies only to residential rental real property. The correct answer is 15-year.","39-year":"39 years applies to nonresidential real property (the building, not the land). The correct answer is 15-year.","Not depreciable":"Only land and other property with no determinable life is not depreciable. The correct answer is 15-year."},"link":"https://www.law.cornell.edu/uscode/text/26/168","points":1,"opts0":["39-year","3-year","15-year","7-year","5-year","27.5-year","Not depreciable"]},{"id":"c7","kind":"dropdown","label":"Bonus depreciation percentage for the machinery","options":["0% (no bonus)","20%","40%","60%","100%"],"answer":"100%","why":"Under P.L. 119-21, qualified property acquired after January 19, 2025 qualifies for 100% bonus depreciation, permanently.","steps":[],"hints":["Look at the law note and the acquisition date.","The phase-down of TCJA was repealed for this property."],"wrong_msgs":{"0% (no bonus)":"Bonus depreciation was not eliminated; it is permanent at 100% for this property. The correct answer is 100%.","20%":"20% was the TCJA phase-down rate for 2026 under prior law, which P.L. 119-21 replaced for property acquired after January 19, 2025. The correct answer is 100%.","40%":"40% is only an optional election for property placed in service in the first tax year ending after January 19, 2025; the default rate is 100%. The correct answer is 100%.","60%":"60% was the TCJA phase-down rate for 2024 placed-in-service property, not for property acquired after January 19, 2025. The correct answer is 100%."},"link":"https://www.law.cornell.edu/uscode/text/26/168","points":1,"opts0":["60%","100%","20%","0% (no bonus)","40%"]}]},{"id":"REG-IV-T-012","area":"IV","format":"numeric_table","difficulty":2,"est_minutes":14,"testable_from":"2026-01-01","law_asof":"2026-09-29","law_note":"","cite":["IRC §62","IRC §63(c)","IRC §25A(i)","IRC §1(j)","Form 8863"],"blueprint":{"area":"IV","group":"A","topic":"Form 1040 computation","task":"Compute taxable income, tax, credits, and refund","skill":"Application"},"params":{"wages":78400,"interest":1250,"hsa":3000,"sli":2000,"std":16100,"aoc":2500,"wh":8100},"vary":{"wages":[72000,75000,78400],"wh":[7000,8100,9000],"sli":[1500,2000,2500],"hsa":[2500,3000,3500]},"guards":["g_agi < 80000","g_agi2 < 85000","g_agi-std > 50400"],"derived":[["g_agi","wages+interest-hsa-sli"],["g_agi2","wages+interest-hsa"],["t22","rnd((rnd(wages+interest-hsa-sli-std)-50400)*0.22)"]],"title":"Form 1040: from income to refund, with the American opportunity credit","scenario":"Marcus Bell is single with no dependents. For 2026 he was a salaried employee and pursued a bachelor's degree part-time. Assume his modified AGI equals his AGI, and he is eligible for every deduction and credit shown in Exhibit 1.","task":"Complete the 2026 Form 1040 for Marcus using the exhibits. Round to the nearest dollar.","exhibits":[{"id":"e1","title":"Tax data","kind":"return_excerpt","body":[["Wages (Form W-2, box 1)","${wages:,}"],["Taxable interest","${interest:,}"],["Health savings account deduction","${hsa:,}"],["Student loan interest deduction (fully allowed)","${sli:,}"],["Standard deduction, single (2026)","${std:,}"],["American opportunity credit before the refundable split (Form 8863, line 7)","${aoc:,}"],["Federal income tax withheld","${wh:,}"]]},{"id":"e_rates","title":"2026 tax rate schedule: single (assumed for this exercise)","kind":"table","body":[["Taxable income over","But not over","Rate"],["$0","$12,400","10%"],["$12,400","$50,400","12%"],["$50,400","$105,700","22%"],["$105,700","$201,775","24%"],["$201,775","$256,225","32%"],["$256,225","$640,600","35%"],["$640,600","-","37%"]]}],"cells":[{"id":"c1","kind":"number","label":"Total income","expr":"wages+interest","fmt":"$","tol":1,"why":"Total income = wages + taxable interest.","steps":["${wages:,} + ${interest:,} = ${c1:,}"],"hints":["Which items are income and which are adjustments?","Adjustments come after total income."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/61","points":1},{"id":"c2","kind":"number","label":"Adjusted gross income","expr":"c1-hsa-sli","fmt":"$","tol":1,"why":"AGI = total income minus above-the-line adjustments (HSA deduction and student loan interest deduction).","steps":["${c1:,} - ${hsa:,} - ${sli:,} = ${c2:,}"],"hints":["Both deductions are adjustments to income.","Subtract both from total income."],"traps":[{"expr":"c1","msg":"You did not subtract the adjustments."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/62","points":1},{"id":"c3","kind":"number","label":"Taxable income","expr":"c2-std","fmt":"$","tol":1,"why":"Taxable income = AGI - standard deduction.","steps":["${c2:,} - ${std:,} = ${c3:,}"],"hints":["Marcus does not itemize.","Subtract the standard deduction."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/63","points":1},{"id":"c4","kind":"number","label":"Regular income tax","expr":"tax_s(c3)","fmt":"$","tol":1,"why":"Apply the bracket schedule to ${c3:,}.","steps":["10% x $12,400 = $1,240","12% x ($50,400 - $12,400) = $4,560","22% x (${c3:,} - $50,400) = ${t22:,}","Total = ${c4:,}"],"hints":["Use the schedule marginally.","Fill 10% and 12% brackets first, then 22% on the rest."],"traps":[{"expr":"c3*0.22","msg":"You applied a flat 22% to all taxable income."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1","points":1},{"id":"c5","kind":"number","label":"Nonrefundable portion of the American opportunity credit","expr":"0.6*aoc","fmt":"$","tol":1,"why":"Only 60% of the credit is nonrefundable; 40% (up to $1,000) is refundable.","steps":["60% x ${aoc:,} = ${c5:,}"],"hints":["The credit is split.","60% nonrefundable, 40% refundable."],"traps":[{"expr":"aoc","msg":"You treated the entire credit as nonrefundable."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/25A","points":1},{"id":"c6","kind":"number","label":"Total tax after the nonrefundable credit","expr":"c4-c5","fmt":"$","tol":1,"why":"Total tax = regular tax - nonrefundable credit.","steps":["${c4:,} - ${c5:,} = ${c6:,}"],"hints":["Subtract the nonrefundable credit from the regular tax.","Use your answers for cells 4 and 5."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/25A","points":1},{"id":"c7","kind":"number","label":"Refundable portion of the American opportunity credit","expr":"0.4*aoc","fmt":"$","tol":1,"why":"40% of the credit is refundable (limited to $1,000), Form 8863 line 8.","steps":["40% x ${aoc:,} = ${c7:,}"],"hints":["It is added to payments.","40% of the credit, at most $1,000."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/25A","points":1},{"id":"c8","kind":"number","label":"Refund (or balance due as a negative number)","expr":"wh+c7-c6","fmt":"$","tol":1,"why":"Refund = withholding + refundable credit - total tax.","steps":["${wh:,} + ${c7:,} - ${c6:,} = ${c8:,}"],"hints":["Payments include withholding and refundable credits.","Payments less total tax."],"traps":[{"expr":"wh-c6","msg":"You omitted the refundable part of the credit."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/25A","points":1}]},{"id":"REG-IV-T-013","area":"IV","format":"numeric_table","difficulty":3,"est_minutes":16,"testable_from":"2026-01-01","law_asof":"2026-09-29","law_note":"","cite":["IRC §1401","IRC §1402(a)","IRC §164(f)","IRC §162(l)","IRC §199A"],"blueprint":{"area":"IV","group":"B","topic":"Self-employment and QBI","task":"Compute SE tax, adjustments, and the qualified business income deduction","skill":"Application"},"params":{"rev":148000,"exp":41000,"sehi":6000,"std":16100},"vary":{"rev":[125000,148000,165000],"exp":[35000,41000,52000],"sehi":[4000,6000,8000]},"guards":["60000 <= rev-exp <= 180000","(rev-exp)-se_tax(rev-exp)/2-sehi-std-0.2*((rev-exp)-se_tax(rev-exp)/2-sehi-std) > 50400"],"derived":[["se_e","rnd((rev-exp)*0.9235)"],["lesser","rnd(min((rev-exp)-se_tax(rev-exp)/2-sehi, (rev-exp)-se_tax(rev-exp)/2-sehi-std))"],["t22","rnd((rnd((rev-exp)-se_tax(rev-exp)/2-sehi-std-0.2*((rev-exp)-se_tax(rev-exp)/2-sehi-std))-50400)*0.22)"]],"title":"Self-employed consultant: SE tax, AGI, QBI deduction, and tax","scenario":"Dana Whitfield is single and has no dependents. She works as a self-employed marketing consultant and has no other income. Her taxable income before the QBI deduction is below the section 199A threshold, so the wage and property limits and the specified service trade or business limits do not apply.","task":"Using the exhibits, compute Dana's 2026 self-employment tax and income tax. Round to the nearest dollar.","exhibits":[{"id":"e1","title":"Schedule C and other data","kind":"return_excerpt","body":[["Gross receipts","${rev:,}"],["Total business expenses","${exp:,}"],["Self-employed health insurance premiums (fully deductible under section 162(l))","${sehi:,}"],["Standard deduction, single (2026)","${std:,}"],["Social security wage base (2026)","$184,500"],["Social security rate","12.4%"],["Medicare rate","2.9%"],["Net earnings factor","92.35%"]]},{"id":"e_rates","title":"2026 tax rate schedule: single (assumed for this exercise)","kind":"table","body":[["Taxable income over","But not over","Rate"],["$0","$12,400","10%"],["$12,400","$50,400","12%"],["$50,400","$105,700","22%"],["$105,700","$201,775","24%"],["$201,775","$256,225","32%"],["$256,225","$640,600","35%"],["$640,600","-","37%"]]}],"cells":[{"id":"c1","kind":"number","label":"Net profit (Schedule C)","expr":"rev-exp","fmt":"$","tol":1,"why":"Net profit = gross receipts - expenses.","steps":["${rev:,} - ${exp:,} = ${c1:,}"],"hints":["Schedule C bottom line.","Receipts less expenses."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1402","points":1},{"id":"c2","kind":"number","label":"Self-employment tax","expr":"se_tax(c1)","fmt":"$","tol":1,"why":"SE earnings = 92.35% x net profit = ${se_e:,}. Tax = 12.4% x SE earnings (below the wage base) + 2.9% x SE earnings.","steps":["${c1:,} x 92.35% = ${se_e:,}","15.3% x ${se_e:,} = ${c2:,}"],"hints":["Start with 92.35% of the net profit.","15.3% because earnings are below the social security wage base."],"traps":[{"expr":"c1*0.153","msg":"You did not apply the 92.35% factor to net profit."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1401","points":1},{"id":"c3","kind":"number","label":"Deduction for one-half of self-employment tax","expr":"se_tax(c1)/2","fmt":"$","tol":1,"why":"Half of the SE tax is an above-the-line deduction (IRC §164(f)).","steps":["${c2:,} / 2 = ${c3:,}"],"hints":["It is an adjustment to income.","One-half of your previous answer."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/164","points":1},{"id":"c4","kind":"number","label":"Adjusted gross income","expr":"c1-c3-sehi","fmt":"$","tol":1,"why":"AGI = net profit - one-half SE tax - self-employed health insurance.","steps":["${c1:,} - ${c3:,} - ${sehi:,} = ${c4:,}"],"hints":["Three items; two are adjustments.","Net profit less both adjustments."],"traps":[{"expr":"c1-sehi","msg":"You forgot the deduction for one-half of SE tax."},{"expr":"c1-c3","msg":"You forgot the health insurance deduction."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/62","points":1},{"id":"c5","kind":"number","label":"Taxable income before the QBI deduction","expr":"c4-std","fmt":"$","tol":1,"why":"Subtract the standard deduction from AGI.","steps":["${c4:,} - ${std:,} = ${c5:,}"],"hints":["Dana does not itemize.","AGI minus standard deduction."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/63","points":1},{"id":"c6","kind":"number","label":"Qualified business income deduction","expr":"0.2*min(c1-c3-sehi, c5)","fmt":"$","tol":1,"why":"Deduction = 20% x lesser of (a) QBI (net profit less half SE tax and SEHI = ${c4:,}) or (b) taxable income before QBI (${c5:,}).","steps":["QBI = ${c4:,}","Lesser of ${c4:,} and ${c5:,} = ${lesser:,}","20% x ${lesser:,} = ${c6:,}"],"hints":["Two limits apply; take the lesser.","20% of the lesser of QBI or taxable income before QBI."],"traps":[{"expr":"0.2*c1","msg":"You used gross net profit. QBI is reduced by half SE tax and the SEHI deduction."},{"expr":"0.2*c4","msg":"You used QBI, but taxable income before the QBI deduction is lower and controls."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/199A","points":1},{"id":"c7","kind":"number","label":"Taxable income","expr":"c5-c6","fmt":"$","tol":1,"why":"Taxable income = taxable income before QBI - QBI deduction.","steps":["${c5:,} - ${c6:,} = ${c7:,}"],"hints":["Subtract the QBI deduction.","Result feeds the tax schedule."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/63","points":1},{"id":"c8","kind":"number","label":"Income tax (excluding SE tax)","expr":"tax_s(c7)","fmt":"$","tol":1,"why":"Apply the schedule to ${c7:,}.","steps":["$5,800 through the 12% bracket","22% x (${c7:,} - $50,400) = ${t22:,}","Total = ${c8:,}"],"hints":["Marginal rates.","10% and 12% brackets are full at $50,400."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1","points":1}]},{"id":"REG-IV-T-014","area":"IV","format":"numeric_table","difficulty":3,"est_minutes":14,"testable_from":"2026-07-01","law_asof":"2026-09-29","law_note":"P.L. 119-21: SALT cap $40,000 for 2025, +1%/yr (2026: $40,400); phase-down above $500,000 (2025) / $505,000 (2026) MAGI. 0.5% AGI floor for itemized charity from 2026 (§170(b)(1)(I)). Verified 2026-09-29 against the text of IRC §164(b)(7) ($40,400 cap, $505,000 threshold) and IRC §170(b)(1)(I) on law.cornell.edu.","cite":["IRC §213(a)","IRC §164(b)(7)","IRC §163(h)(3)","IRC §170(b)(1)(I)"],"blueprint":{"area":"IV","group":"C","topic":"Itemized deductions","task":"Compute itemized deductions and compare with the standard deduction","skill":"Application"},"params":{"agi":300000,"med":30000,"sti":34000,"prop":9600,"mort_int":42000,"loan":900000,"chg":12000,"std":32200,"salt_cap":40400},"vary":{"agi":[260000,300000,340000],"med":[26000,30000,36000],"sti":[26000,34000,38000],"chg":[9000,12000,15000]},"guards":["med > 0.075*agi","chg > 0.005*agi"],"derived":[["fl","rnd(0.075*agi)"],["cfl","rnd(0.005*agi)"],["st","sti+prop"]],"title":"Itemized deductions: medical, SALT cap, mortgage interest, charity","scenario":"Luis and Carmen Ortega file jointly for 2026. Their AGI is ${agi:,}. They are under age 65, and are not subject to any phase-out of itemized deductions other than as described in the exhibit.","task":"Compute the Ortegas' deductible amounts and decide between itemizing and the standard deduction. Round to the nearest dollar.","exhibits":[{"id":"e1","title":"Expenses paid in 2026","kind":"table","body":[["Item","Amount"],["Unreimbursed medical expenses (all qualifying)","${med:,}"],["State income tax paid","${sti:,}"],["Real property taxes on their home","${prop:,}"],["Interest paid on a home acquisition loan (loan balance ${loan:,}, taken out in 2022)","${mort_int:,}"],["Cash gifts to public charities","${chg:,}"],["Standard deduction, married filing jointly (2026)","${std:,}"]]},{"id":"e2","title":"Law assumptions for 2026","kind":"statute_note","body":"Medical expenses are deductible only above 7.5% of AGI.\nState and local tax deduction cap for 2026: ${salt_cap:,}. The cap is reduced only if modified AGI exceeds $505,000, which does not apply here.\nHome acquisition debt limit: $750,000; interest is deductible in the proportion of the limit to the loan balance.\nFor tax years beginning after 2025, charitable contributions of an itemizer are deductible only to the extent they exceed 0.5% of AGI (the 60% cash limit is not an issue here)."}],"cells":[{"id":"c1","kind":"number","label":"Deductible medical expenses","expr":"max(0, med-0.075*agi)","fmt":"$","tol":1,"why":"Only medical expenses above 7.5% of AGI are deductible: ${med:,} - 7.5% x ${agi:,}.","steps":["7.5% x ${agi:,} = ${fl:,}","${med:,} - ${fl:,} = ${c1:,}"],"hints":["Subtract a floor.","7.5% of AGI."],"traps":[{"expr":"med","msg":"You did not apply the 7.5% AGI floor."},{"expr":"max(0, med-0.10*agi)","msg":"You used the 10% floor."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/213","points":1},{"id":"c2","kind":"number","label":"Deductible state and local taxes","expr":"min(sti+prop, salt_cap)","fmt":"$","tol":1,"why":"State income tax plus property tax = ${st:,}, limited to the ${salt_cap:,} cap.","steps":["${sti:,} + ${prop:,} = ${st:,}","Lesser of ${st:,} and ${salt_cap:,} = ${c2:,}"],"hints":["Add both taxes, then check the cap.","The cap is in the law assumptions."],"traps":[{"expr":"sti+prop","msg":"You did not apply the SALT cap."},{"expr":"min(sti+prop, 10000)","msg":"You used the old $10,000 cap."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/164","points":1},{"id":"c3","kind":"number","label":"Deductible home mortgage interest","expr":"mort_int*min(loan,750000)/loan","fmt":"$","tol":1,"why":"Interest is limited to acquisition debt of $750,000: ${mort_int:,} x $750,000 / ${loan:,}.","steps":["$750,000 / ${loan:,} = ratio","${mort_int:,} x ratio = ${c3:,}"],"hints":["Only debt up to a limit counts.","Prorate interest by limit/balance."],"traps":[{"expr":"mort_int","msg":"You deducted all interest, ignoring the $750,000 limit."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/163","points":1},{"id":"c4","kind":"number","label":"Deductible charitable contributions","expr":"max(0, chg-0.005*agi)","fmt":"$","tol":1,"why":"Contributions are deductible only above 0.5% of AGI: ${chg:,} - 0.5% x ${agi:,}.","steps":["0.5% x ${agi:,} = ${cfl:,}","${chg:,} - ${cfl:,} = ${c4:,}"],"hints":["A new floor applies for 2026.","0.5% of AGI."],"traps":[{"expr":"chg","msg":"You ignored the 0.5% floor."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/170","points":1},{"id":"c5","kind":"number","label":"Total itemized deductions","expr":"c1+c2+c3+c4","fmt":"$","tol":1,"why":"Sum of the four deductible amounts.","steps":["${c1:,} + ${c2:,} + ${c3:,} + ${c4:,} = ${c5:,}"],"hints":["Add your four previous answers.","Then compare with the standard deduction."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/63","points":1},{"id":"c6","kind":"number","label":"Deduction the Ortegas should claim","expr":"max(c5, std)","fmt":"$","tol":1,"why":"Claim the larger of itemized deductions and the standard deduction of ${std:,}.","steps":["max(${c5:,}, ${std:,}) = ${c6:,}"],"hints":["Choose the greater.","Compare your total with the standard deduction."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/63","points":1},{"id":"c7","kind":"number","label":"Taxable income","expr":"agi-c6","fmt":"$","tol":1,"why":"Taxable income = AGI - deduction.","steps":["${agi:,} - ${c6:,} = ${c7:,}"],"hints":["Assume no QBI deduction or other items.","AGI minus the chosen deduction."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/63","points":1}]},{"id":"REG-IV-T-015","area":"IV","format":"numeric_table","difficulty":3,"est_minutes":14,"testable_from":"2026-01-01","law_asof":"2026-09-29","law_note":"","cite":["IRC §1211(b)","IRC §1212(b)","IRC §1(h)"],"blueprint":{"area":"IV","group":"D","topic":"Capital gains and losses","task":"Net capital gains and losses, apply limits, carryovers, and preferential rates","skill":"Application"},"params":{"stg":8000,"stl":12000,"ltg":5000,"ltl":9000,"ord_ti":30050,"ltcg":40000,"z_top":49450,"f_top":545500},"vary":{"stg":[7000,8000,9000],"stl":[11000,12000,13000],"ltg":[4000,5000,6000],"ltl":[8000,9000,10000],"ord_ti":[30050,32050,34050],"ltcg":[40000,44000,48000]},"guards":["stg-stl < 0","ltg-ltl < 0","-(stg-stl+ltg-ltl) > 3000","-(stg-stl) > 3000","ltcg > z_top-ord_ti"],"derived":[["tl","-(stg-stl+ltg-ltl)"],["nst","stl-stg"],["nlt","ltl-ltg"],["room","z_top-ord_ti"],["rest","ltcg-(z_top-ord_ti)"]],"title":"Capital loss limits, carryovers, and tax on net long-term gain","scenario":"Nora Patel is single. In Scenario A she has only the capital transactions below. In Scenario B (unrelated facts for a different year) she has ordinary taxable income and a net long-term capital gain. Enter losses and carryovers as positive amounts unless the cell says otherwise.","task":"Using the exhibits, complete both scenarios. Round to the nearest dollar.","exhibits":[{"id":"e1","title":"Scenario A: capital transactions for the year","kind":"table","body":[["Item","Amount"],["Short-term capital gains","${stg:,}"],["Short-term capital losses","${stl:,}"],["Long-term capital gains","${ltg:,}"],["Long-term capital losses","${ltl:,}"]]},{"id":"e2","title":"Scenario B: data and rate thresholds (assumed for 2026, single)","kind":"table","body":[["Item","Amount"],["Ordinary taxable income (excluding the long-term gain)","${ord_ti:,}"],["Net long-term capital gain (all taxed at preferential rates)","${ltcg:,}"],["Top of the 0% capital gain bracket (taxable income)","${z_top:,}"],["Top of the 15% bracket (taxable income)","${f_top:,}"]]}],"cells":[{"id":"c1","kind":"number","label":"Scenario A: net short-term capital gain or (loss); enter a loss as a negative number","expr":"stg-stl","fmt":"$","tol":1,"why":"Short-term gains minus short-term losses.","steps":["${stg:,} - ${stl:,} = ${c1:,}"],"hints":["Net within each holding-period group first.","Short-term with short-term."],"traps":[],"ecf":false,"link":"https://www.law.cornell.edu/uscode/text/26/1212","points":1},{"id":"c2","kind":"number","label":"Scenario A: net long-term capital gain or (loss); enter a loss as a negative number","expr":"ltg-ltl","fmt":"$","tol":1,"why":"Long-term gains minus long-term losses.","steps":["${ltg:,} - ${ltl:,} = ${c2:,}"],"hints":["Long-term with long-term.","Same as the previous step for the other group."],"traps":[],"ecf":false,"link":"https://www.law.cornell.edu/uscode/text/26/1212","points":1},{"id":"c3","kind":"number","label":"Scenario A: capital loss deductible against ordinary income","expr":"min(3000, -(c1+c2))","fmt":"$","tol":1,"why":"Both nets are losses, so the total net capital loss ${tl:,} is deductible up to $3,000 against ordinary income.","steps":["Total net loss = ${tl:,}","Deductible = $3,000"],"hints":["There is an annual limit.","$3,000 for a single taxpayer."],"traps":[{"expr":"-(c1+c2)","msg":"You deducted the entire net loss. The annual limit is $3,000."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1211","points":1},{"id":"c4","kind":"number","label":"Scenario A: total capital loss carried to next year","expr":"-(c1+c2)-c3","fmt":"$","tol":1,"why":"Carryover = total net capital loss - amount deducted.","steps":["${tl:,} - $3,000 = ${c4:,}"],"hints":["What remains after the deduction?","Net loss less the amount deducted."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1212","points":1},{"id":"c5","kind":"number","label":"Scenario A: short-term portion of the carryover","expr":"-c1-min(c3,-c1)","fmt":"$","tol":1,"why":"The $3,000 deduction uses the net short-term loss first; the remaining short-term loss carries over as short-term.","steps":["Net ST loss ${nst:,} - $3,000 used = ${c5:,}"],"hints":["The deduction uses the short-term loss first.","Short-term loss less the amount deducted."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1212","points":1},{"id":"c6","kind":"number","label":"Scenario A: long-term portion of the carryover","expr":"-c2-(c3-min(c3,-c1))","fmt":"$","tol":1,"why":"The long-term loss is used only after the short-term loss is exhausted, so the long-term loss carries over in full.","steps":["Net LT loss ${nlt:,} - amount used from LT ($0) = ${c6:,}"],"hints":["Short-term losses are absorbed first.","Total carryover less the short-term portion."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1212","points":1},{"id":"c7","kind":"number","label":"Scenario B: net long-term gain taxed at 0%","expr":"min(ltcg, max(0, z_top-ord_ti))","fmt":"$","tol":1,"why":"The 0% bracket has room of ${z_top:,} - ${ord_ti:,} = ${room:,} of taxable income.","steps":["Room = ${z_top:,} - ${ord_ti:,} = ${room:,}","Gain in 0% bracket = ${c7:,}"],"hints":["Stack the gain on top of ordinary income.","Room left below the 0% bracket top."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1","points":1},{"id":"c8","kind":"number","label":"Scenario B: tax on the net long-term gain (15% rate, none reaches 20%)","expr":"0.15*(ltcg-c7)","fmt":"$","tol":1,"why":"The rest of the gain is taxed at 15%: (${ltcg:,} - ${c7:,}) x 15%.","steps":["${ltcg:,} - ${c7:,} = ${rest:,}","15% x ${rest:,} = ${c8:,}"],"hints":["Part of the gain is already in the 0% bracket.","15% of the gain above the 0% room."],"traps":[{"expr":"0.15*ltcg","msg":"You applied 15% to the whole gain, ignoring the 0% bracket."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1","points":1}]},{"id":"REG-IV-T-016","area":"IV","format":"document_review","difficulty":3,"est_minutes":14,"testable_from":"2026-07-01","law_asof":"2026-09-29","law_note":"Statements 4-6 rely on P.L. 119-21 (OBBBA): CTC $2,200, gambling loss 90% rule, qualified tips deduction; testable from 2026-07-01.","cite":["IRC §67(g)","IRC §408A(d)","IRC §24","IRC §165(d)","IRC §224"],"blueprint":{"area":"IV","group":"A","topic":"Individual return positions","task":"Identify errors in return explanations under current law","skill":"Analysis"},"params":{},"vary":{},"guards":[],"derived":[],"title":"Review of a staff summary of return positions (2026 law)","scenario":"You are the reviewer for a return prepared by a junior staff member for Roman and Ilse Kovac (married filing jointly). The staff member wrote the explanations below to the client. Assume all facts stated are true.","task":"For each numbered statement, choose the option that makes the statement correct for the 2026 tax year. Choose 'Keep as written' if it is already correct.","exhibits":[{"id":"e1","title":"Draft email to the clients","kind":"email","body":"1. Alimony Roman pays under the divorce decree from his first marriage (finalized in 2023) is deductible above the line on your return.\n2. Ilse works as an employee at home for her employer's convenience. Her unreimbursed home office costs are deductible as an itemized deduction.\n3. Roman's Roth IRA distribution at age 63 from a Roth IRA whose first contribution was made 8 years ago is a qualified distribution and is excluded from income.\n4. You may claim a child tax credit of $2,000 for each of your two qualifying children.\n5. Your gambling losses of $9,000 (winnings $12,000) are deductible in full as an itemized deduction, up to your winnings.\n6. All tips Ilse reported on her Form W-2 are fully deductible, without a dollar limit."}],"cells":[{"id":"c1","kind":"dropdown","label":"Statement 1: alimony paid","options":["Keep as written","Revise: alimony under a post-2018 divorce instrument is not deductible by the payer (and not income to the recipient)","Revise: alimony is deductible only as an itemized deduction"],"answer":"Revise: alimony under a post-2018 divorce instrument is not deductible by the payer (and not income to the recipient)","why":"For divorce or separation instruments executed after 2018, alimony is not deductible by the payer and not includible by the recipient (former IRC §215 and §71 repealed by TCJA §11051).","steps":[],"hints":["Look at the date of the decree.","Post-2018 decrees follow the repeal."],"wrong_msgs":{"Keep as written":"The above-the-line alimony deduction applies only to pre-2019 instruments.","Revise: alimony is deductible only as an itemized deduction":"It is not deductible at all for post-2018 instruments."},"cite":"IRC §71 (repealed); TCJA §11051","link":"https://www.law.cornell.edu/uscode/text/26/215","points":1,"opts0":["Revise: alimony under a post-2018 divorce instrument is not deductible by the payer (and not income to the recipient)","Revise: alimony is deductible only as an itemized deduction","Keep as written"]},{"id":"c2","kind":"dropdown","label":"Statement 2: employee home office","options":["Keep as written","Revise: unreimbursed employee expenses (including a home office) are not deductible for 2026","Revise: the costs are deductible on Schedule C"],"answer":"Revise: unreimbursed employee expenses (including a home office) are not deductible for 2026","why":"Miscellaneous itemized deductions subject to the 2% floor, including unreimbursed employee expenses, are not allowed for tax years after 2017; P.L. 119-21 made the elimination permanent (IRC §67(g)).","steps":[],"hints":["Employee versus self-employed.","Suspended and now permanently eliminated."],"wrong_msgs":{"Keep as written":"Employee business expenses are not deductible.","Revise: the costs are deductible on Schedule C":"Ilse is an employee, not self-employed."},"cite":"IRC §67(g)","link":"https://www.law.cornell.edu/uscode/text/26/67","points":1,"opts0":["Revise: unreimbursed employee expenses (including a home office) are not deductible for 2026","Keep as written","Revise: the costs are deductible on Schedule C"]},{"id":"c3","kind":"dropdown","label":"Statement 3: Roth IRA distribution","options":["Keep as written","Revise: the earnings are taxable because the account is under 10 years old","Revise: a Roth distribution is never tax-free"],"answer":"Keep as written","why":"A distribution is qualified if made after age 59 1/2 and after the 5-tax-year period beginning with the first contribution year (IRC §408A(d)(2)). Roman is 63 and the account is 8 years old.","steps":[],"hints":["Two tests: age and the five-year period.","Both are met."],"wrong_msgs":{"Revise: the earnings are taxable because the account is under 10 years old":"The holding period is 5 tax years, not 10.","Revise: a Roth distribution is never tax-free":"Qualified distributions are tax-free."},"cite":"IRC §408A(d)(2)","link":"https://www.law.cornell.edu/uscode/text/26/408A","points":1,"opts0":["Revise: a Roth distribution is never tax-free","Keep as written","Revise: the earnings are taxable because the account is under 10 years old"]},{"id":"c4","kind":"dropdown","label":"Statement 4: child tax credit amount","options":["Keep as written","Revise: $2,200 per qualifying child","Revise: $3,000 per qualifying child"],"answer":"Revise: $2,200 per qualifying child","why":"P.L. 119-21 increased the credit to $2,200 per qualifying child for 2025 and indexes it for inflation after 2025 (IRC §24(h)); Rev. Proc. 2025-32 shows $2,200 for 2026.","steps":[],"hints":["The amount was increased in 2025.","$2,200."],"wrong_msgs":{"Keep as written":"$2,000 was the prior amount.","Revise: $3,000 per qualifying child":"That is not the credit amount."},"cite":"IRC §24(h)","link":"https://www.law.cornell.edu/uscode/text/26/24","points":1,"opts0":["Keep as written","Revise: $2,200 per qualifying child","Revise: $3,000 per qualifying child"]},{"id":"c5","kind":"dropdown","label":"Statement 5: gambling losses","options":["Keep as written","Revise: 90% of the losses are deductible, limited to winnings","Revise: no gambling losses are deductible for 2026"],"answer":"Revise: 90% of the losses are deductible, limited to winnings","why":"For tax years beginning after 2025, gambling losses are deductible only up to 90% of the losses and limited to winnings (IRC §165(d), as amended by P.L. 119-21). Here 90% x $9,000 = $8,100.","steps":[],"hints":["The law changed for 2026.","Only part of the losses is allowed."],"wrong_msgs":{"Keep as written":"The 100% rule applied through 2025.","Revise: no gambling losses are deductible for 2026":"Losses are still deductible up to winnings, at 90%."},"cite":"IRC §165(d)","link":"https://www.law.cornell.edu/uscode/text/26/165","points":1,"opts0":["Keep as written","Revise: 90% of the losses are deductible, limited to winnings","Revise: no gambling losses are deductible for 2026"]},{"id":"c6","kind":"dropdown","label":"Statement 6: qualified tips deduction","options":["Keep as written","Revise: the deduction is limited to tips from occupations that customarily and regularly receive tips, up to $25,000, and phases out above $150,000 MAGI ($300,000 joint)","Revise: the deduction is allowed only as an itemized deduction"],"answer":"Revise: the deduction is limited to tips from occupations that customarily and regularly receive tips, up to $25,000, and phases out above $150,000 MAGI ($300,000 joint)","why":"P.L. 119-21 allows a deduction for qualified tips (2025-2028): occupations customarily receiving tips, annual cap of $25,000, reduced by $100 per $1,000 of MAGI above $150,000 ($300,000 joint), allowed to nonitemizers too (IRC §224).","steps":[],"hints":["It is not unlimited.","Cap, occupation test, and phase-out."],"wrong_msgs":{"Keep as written":"The deduction has an occupation test, a $25,000 cap, and a phase-out.","Revise: the deduction is allowed only as an itemized deduction":"It is available whether or not the taxpayer itemizes."},"cite":"IRC §224","link":"https://www.law.cornell.edu/uscode/text/26/224","points":1,"opts0":["Keep as written","Revise: the deduction is limited to tips from occupations that customarily and regularly receive tips, up to $25,000, and phases out above $150,000 MAGI ($300,000 joint)","Revise: the deduction is allowed only as an itemized deduction"]}]},{"id":"REG-IV-T-017","area":"IV","format":"research","difficulty":2,"est_minutes":10,"testable_from":"2026-01-01","law_asof":"2026-09-29","law_note":"","cite":["IRC §408A","IRC §25A","IRC §24","IRC §221","IRC §469","IRC §280A"],"blueprint":{"area":"IV","group":"A","topic":"Research: individual tax","task":"Research and cite authority for individual income tax issues","skill":"Application"},"params":{},"vary":{},"guards":[],"derived":[],"title":"Locate the authority: individual income tax","scenario":"A client asks six questions about individual income tax rules. Identify the primary authority for each answer.","task":"For each question, enter the Internal Revenue Code citation (for example, 'IRC 1402(a)(13)'). Give a subsection or paragraph only when the question asks for it.","exhibits":[{"id":"e1","title":"Questions","kind":"email","body":"1. Which section and subsection define a qualified distribution from a Roth IRA?\n2. Which section provides the American opportunity credit and the lifetime learning credit? (Section only.)\n3. Which section provides the child tax credit? (Section only.)\n4. Which section provides the deduction for interest on qualified education loans? (Section only.)\n5. Which section limits deductions for passive activity losses? (Section only.)\n6. Which section, subsection, and paragraph provide when a dwelling unit is treated as a residence of the taxpayer for the vacation-home rules (more than 14 days or 10% of rental days)?"}],"cells":[{"id":"c1","kind":"citation","label":"Question 1: qualified Roth IRA distribution","ask":"IRC section (and subsection if asked)","accept":["408A(d)(2)"],"partial":["408A","408A(d)"],"link":"https://www.law.cornell.edu/uscode/text/26/408A","why":"IRC §408A(d)(2) defines a qualified distribution (five-year period plus age 59 1/2, death, disability, or first-time home purchase).","steps":[],"hints":["Roth IRAs are in section 408A.","Subsection (d) covers distribution rules; paragraph (2) defines qualified."],"points":1},{"id":"c2","kind":"citation","label":"Question 2: education credits","ask":"IRC section (and subsection if asked)","accept":["25A"],"partial":["25A(a)","25A(b)"],"link":"https://www.law.cornell.edu/uscode/text/26/25A","why":"IRC §25A provides the Hope/American opportunity credit and the lifetime learning credit.","steps":[],"hints":["Subpart A of part IV; credits for personal expenses.","Section 25A."],"points":1},{"id":"c3","kind":"citation","label":"Question 3: child tax credit","ask":"IRC section (and subsection if asked)","accept":["24"],"partial":["24(a)"],"link":"https://www.law.cornell.edu/uscode/text/26/24","why":"IRC §24 child tax credit.","steps":[],"hints":["Part IV, subpart A.","Section 24."],"points":1},{"id":"c4","kind":"citation","label":"Question 4: student loan interest deduction","ask":"IRC section (and subsection if asked)","accept":["221"],"partial":[],"link":"https://www.law.cornell.edu/uscode/text/26/221","why":"IRC §221 deduction for interest on education loans.","steps":[],"hints":["Part VII adjustments.","Section 221."],"points":1},{"id":"c5","kind":"citation","label":"Question 5: passive activity loss limit","ask":"IRC section (and subsection if asked)","accept":["469"],"partial":["469(a)"],"link":"https://www.law.cornell.edu/uscode/text/26/469","why":"IRC §469 passive activity losses and credits limited.","steps":[],"hints":["Subchapter E.","Section 469."],"points":1},{"id":"c6","kind":"citation","label":"Question 6: vacation-home residence test","ask":"IRC section (and subsection if asked)","accept":["280A(d)(1)"],"partial":["280A","280A(d)"],"link":"https://www.law.cornell.edu/uscode/text/26/280A","why":"IRC §280A(d)(1): a dwelling unit is used as a residence if personal use exceeds the greater of 14 days or 10% of the days it is rented.","steps":[],"hints":["Section 280A limits deductions for dwelling units used as residences.","Subsection (d), paragraph (1)."],"points":1}]},{"id":"REG-IV-T-018","area":"IV","format":"dropdown_judgment","difficulty":2,"est_minutes":12,"testable_from":"2026-01-01","law_asof":"2026-09-29","law_note":"","cite":["IRC §152(c)","IRC §152(d)","IRC §2(a)","IRC §2(b)"],"blueprint":{"area":"IV","group":"A","topic":"Filing status and dependents","task":"Determine dependency tests and filing status","skill":"Application"},"params":{},"vary":{},"guards":[],"derived":[],"title":"Dependents and filing status","scenario":"Ana Ruiz is unmarried and paid more than half the cost of keeping up her home for all of 2026. The individuals below are described in the exhibit. Assume none of them files a joint return, none is a qualifying child of another taxpayer, all are U.S. citizens with valid SSNs, and the 2026 gross income limit for a qualifying relative is $5,300.","task":"For each person, select the relationship test result that applies to Ana. For the last two cells, select the filing status.","exhibits":[{"id":"e1","title":"Individuals","kind":"table","body":[["Person","Facts"],["Sofia (daughter)","Age 22, full-time student for 9 months, lived with Ana 8 months in 2026, provided 30% of her own support, gross income $6,000."],["Rosa (mother)","Age 70, lives in her own apartment, gross income $4,200, Ana provides 70% of her support."],["Mark (unrelated friend)","Lived in Ana's home all year as a member of the household (no violation of local law), gross income $3,000, Ana provides over half his support."],["Leo (nephew)","Age 19, not a student, lived with Ana all year, gross income $9,000, Ana provides over half his support."],["Diego (son)","Age 26, not a student or disabled, lived with Ana all year, gross income $2,000, Ana provides over half his support."]]},{"id":"e2","title":"Second taxpayer","kind":"notes","body":"Carlos Vega's wife died in June 2024. He has not remarried. He maintained a home that was the main home of his dependent 9-year-old son for all of 2025 and 2026, and he paid more than half of the cost of keeping up the home. What is Carlos's 2026 filing status?"}],"cells":[{"id":"c1","kind":"dropdown","label":"Sofia","options":["Qualifying child","Qualifying relative","Neither"],"answer":"Qualifying child","why":"Sofia is under 24 and a full-time student (age test), lived with Ana for more than half the year (residency), and did not provide more than half of her own support. Gross income is not tested for a qualifying child.","steps":[],"hints":["Age test for students is under 24.","Gross income does not matter for a child."],"wrong_msgs":{"Qualifying relative":"A person who is a qualifying child cannot be a qualifying relative.","Neither":"All qualifying child tests are met."},"link":"https://www.law.cornell.edu/uscode/text/26/152","points":1,"opts0":["Neither","Qualifying relative","Qualifying child"]},{"id":"c2","kind":"dropdown","label":"Rosa","options":["Qualifying child","Qualifying relative","Neither"],"answer":"Qualifying relative","why":"Rosa is a relative who does not live with Ana. She is not a qualifying child (age). Gross income $4,200 is under $5,300, and Ana provides more than half of her support.","steps":[],"hints":["She fails the age and residency tests for a qualifying child.","Check the income limit."],"wrong_msgs":{"Qualifying child":"A parent cannot be a qualifying child.","Neither":"Gross income and support tests are met."},"link":"https://www.law.cornell.edu/uscode/text/26/152","points":1,"opts0":["Qualifying relative","Neither","Qualifying child"]},{"id":"c3","kind":"dropdown","label":"Mark","options":["Qualifying child","Qualifying relative","Neither"],"answer":"Qualifying relative","why":"An unrelated person who lives with the taxpayer all year as a member of the household can be a qualifying relative if the income and support tests are met.","steps":[],"hints":["A relationship test can be met by living in the household.","Check income and support."],"wrong_msgs":{"Qualifying child":"A qualifying child must be a child, sibling, or descendant.","Neither":"Member-of-household status satisfies the relationship test."},"link":"https://www.law.cornell.edu/uscode/text/26/152","points":1,"opts0":["Qualifying child","Qualifying relative","Neither"]},{"id":"c4","kind":"dropdown","label":"Leo","options":["Qualifying child","Qualifying relative","Neither"],"answer":"Neither","why":"Leo fails the qualifying-child age test (19, not a student) and fails the qualifying-relative gross income test ($9,000 > $5,300).","steps":[],"hints":["Age 19 and not a student.","Compare his income to $5,300."],"wrong_msgs":{"Qualifying child":"Under 19 or under 24 for students only.","Qualifying relative":"His gross income exceeds the limit."},"link":"https://www.law.cornell.edu/uscode/text/26/152","points":1,"opts0":["Neither","Qualifying relative","Qualifying child"]},{"id":"c5","kind":"dropdown","label":"Diego","options":["Qualifying child","Qualifying relative","Neither"],"answer":"Qualifying relative","why":"Diego is too old to be a qualifying child (26, not a student), but he can be a qualifying relative: gross income $2,000 < $5,300 and Ana provides more than half his support.","steps":[],"hints":["Age 26 is too old for the child test.","Try the relative tests."],"wrong_msgs":{"Qualifying child":"Age 26 fails the child age test.","Neither":"He meets all qualifying relative tests."},"link":"https://www.law.cornell.edu/uscode/text/26/152","points":1,"opts0":["Qualifying relative","Neither","Qualifying child"]},{"id":"c6","kind":"dropdown","label":"Ana's filing status for 2026","options":["Single","Head of household","Married filing jointly","Qualifying surviving spouse"],"answer":"Head of household","why":"Ana is unmarried, paid more than half the cost of keeping up her home, and Sofia (a qualifying child) lived with her more than half of the year.","steps":[],"hints":["Unmarried with a qualifying person.","Head of household."],"wrong_msgs":{"Single":"She qualifies for the better status.","Married filing jointly":"Ana is unmarried.","Qualifying surviving spouse":"Ana is not a surviving spouse."},"link":"https://www.law.cornell.edu/uscode/text/26/2","points":1,"opts0":["Married filing jointly","Single","Qualifying surviving spouse","Head of household"]},{"id":"c7","kind":"dropdown","label":"Carlos's filing status for 2026","options":["Single","Head of household","Married filing jointly","Qualifying surviving spouse"],"answer":"Qualifying surviving spouse","why":"Carlos may use qualifying surviving spouse status for the two tax years after the year of death (2025 and 2026), if he has not remarried and maintains a home for his dependent child.","steps":[],"hints":["Look at the year of death.","Two years after the year of the spouse's death."],"wrong_msgs":{"Head of household":"A surviving spouse with a dependent child can use the more favorable status.","Single":"He qualifies for a better status.","Married filing jointly":"His spouse died in 2024, before the 2026 tax year."},"link":"https://www.law.cornell.edu/uscode/text/26/2","points":1,"opts0":["Married filing jointly","Qualifying surviving spouse","Single","Head of household"]}]},{"id":"REG-V-T-019","area":"V","format":"numeric_table","difficulty":3,"est_minutes":16,"testable_from":"2026-01-01","law_asof":"2026-09-29","law_note":"Tax year 2025 by design: the 1% floor on corporate charitable deductions (IRC §170(b)(2)(A), P.L. 119-21) applies to tax years beginning after 2025, so it is not part of this TBS. The 10% limit is figured after the NOL carryforward deduction (Form 1120 instructions, line 19); the NOL here is small enough that the 80% cap does not bind, which avoids a circular computation.","cite":["IRC §170(b)(2)","IRC §243(a)(1)","IRC §243(c)","IRC §172(a)(2)","IRC §11(b)","IRC §274(n)"],"blueprint":{"area":"V","group":"A","topic":"C corporation taxable income","task":"Compute corporate taxable income including charity limit, DRD, and NOL","skill":"Application"},"params":{"book":900000,"muni":30000,"meals":40000,"dep":70000,"divs":100000,"chg":120000,"nol":300000},"vary":{"book":[800000,900000,1000000],"chg":[100000,120000,140000],"divs":[80000,100000,120000],"nol":[250000,300000,350000]},"guards":["chg > 0.10*(cbase-nol)","nol < 0.8*ti0"],"derived":[["nd","rnd(0.5*meals)"],["cbase","rnd(book+chg-muni+0.5*meals-dep)"],["cb2","rnd(book+chg-muni+0.5*meals-dep-nol)"],["lim","rnd(0.10*(book+chg-muni+0.5*meals-dep-nol))"],["drd","rnd(0.65*divs)"],["drdlim","rnd(0.65*(book+chg-muni+0.5*meals-dep-min(chg,0.10*(book+chg-muni+0.5*meals-dep-nol))))"],["ti0","rnd(book+chg-muni+0.5*meals-dep-min(chg,0.10*(book+chg-muni+0.5*meals-dep-nol))-min(0.65*divs,0.65*(book+chg-muni+0.5*meals-dep-min(chg,0.10*(book+chg-muni+0.5*meals-dep-nol)))))"],["nlim","rnd(0.8*(book+chg-muni+0.5*meals-dep-min(chg,0.10*(book+chg-muni+0.5*meals-dep-nol))-min(0.65*divs,0.65*(book+chg-muni+0.5*meals-dep-min(chg,0.10*(book+chg-muni+0.5*meals-dep-nol))))))"]],"title":"C corporation: book-to-tax adjustments and taxable income","scenario":"Kestrel Components Inc. is a calendar-year C corporation (no affiliated group). For its 2025 return it starts from book income before federal income tax. All items are as described in the exhibit; assume no other items and use the 21% corporate rate.","task":"Compute the corporation's taxable income and regular tax using the exhibit. Round to the nearest dollar.","exhibits":[{"id":"e1","title":"Book income and reconciling items (2025)","kind":"table","body":[["Item","Amount"],["Book income before federal income tax (after all items below)","${book:,}"],["Municipal bond interest included in book income (tax-exempt)","${muni:,}"],["Meals expense deducted in book income (50% limit applies for tax)","${meals:,}"],["Tax depreciation in excess of book depreciation","${dep:,}"],["Dividends from a 25%-owned domestic corporation, included in book income","${divs:,}"],["Cash contributions to public charities, deducted in book income","${chg:,}"],["Net operating loss carryforward from 2023 (post-2017 loss)","${nol:,}"]]},{"id":"e2","title":"Ordering rules","kind":"notes","body":"Charitable contributions are limited to 10% of taxable income computed before the charitable deduction and the dividends-received deduction, and without regard to any NOL carryback.\nThe dividends-received deduction is a percentage of the dividends received, limited to the same percentage of taxable income computed without the NOL and the DRD.\nThe NOL deduction is limited to 80% of taxable income computed without the NOL deduction (but after the DRD)."}],"cells":[{"id":"c1","kind":"number","label":"Charitable contribution deduction allowed for 2025","expr":"min(chg, 0.10*(book+chg-muni+0.5*meals-dep-nol))","fmt":"$","tol":1,"why":"Base for the 10% limit = taxable income before the charity deduction and the DRD but after the NOL carryforward deduction (Form 1120 instructions, line 19: only NOL carrybacks are ignored). Income before those items = book income + contributions added back - muni interest + nondeductible meals - excess tax depreciation = ${cbase:,}; less the ${nol:,} NOL deduction = ${cb2:,}. Limit = 10% x ${cb2:,}.","steps":["Income before charity, DRD, and NOL = ${book:,} + ${chg:,} - ${muni:,} + ${nd:,} - ${dep:,} = ${cbase:,}","Less the NOL deduction of ${nol:,} (fully allowed, see cell 5) = ${cb2:,}","10% x ${cb2:,} = ${lim:,}","Allowed = lesser of ${chg:,} and ${lim:,} = ${c1:,}"],"hints":["The base is taxable income before charity and the DRD but after the NOL carryforward deduction; only NOL carrybacks are ignored.","Adjust book income: add back the charity, remove muni interest, add back half the meals, subtract excess depreciation, then subtract the NOL deduction."],"traps":[{"expr":"chg","msg":"You deducted the entire contribution and ignored the 10% limit."},{"expr":"min(chg, 0.10*book)","msg":"You applied 10% to book income rather than to adjusted taxable income."},{"expr":"min(chg, 0.10*(book+chg-muni+0.5*meals-dep))","msg":"You ignored the NOL carryforward deduction. Only NOL carrybacks are left out of the 10% base; a carryforward reduces it."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/170","points":1},{"id":"c2","kind":"number","label":"Charitable contribution carryforward","expr":"chg-c1","fmt":"$","tol":1,"why":"The excess over the limit carries forward for five years (IRC §170(d)(2)).","steps":["${chg:,} - ${c1:,} = ${c2:,}"],"hints":["What part was not allowed this year?","Contribution less allowed deduction."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/170","points":1},{"id":"c3","kind":"number","label":"Taxable income before the dividends-received deduction and NOL deduction","expr":"book+chg-muni+0.5*meals-dep-c1","fmt":"$","tol":1,"why":"Start from the base (which already adds back the charity and the other reconciling items) and subtract the allowed charity deduction.","steps":["${cbase:,} - ${c1:,} = ${c3:,}"],"hints":["Use the base from cell 1.","Base less the allowed charity deduction."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/63","points":1},{"id":"c4","kind":"number","label":"Dividends-received deduction","expr":"min(0.65*divs, 0.65*c3)","fmt":"$","tol":1,"why":"A 20%-or-more owned domestic corporation qualifies for the 65% DRD (IRC §243(c)); the limit is 65% of taxable income before the DRD and NOL, which is not binding here.","steps":["65% x ${divs:,} = ${drd:,}","Limit 65% x ${c3:,} = ${drdlim:,}","DRD = ${c4:,}"],"hints":["The DRD percentage depends on ownership.","20% to under 80% ownership: 65%."],"traps":[{"expr":"0.5*divs","msg":"You used 50%, which applies below 20% ownership."},{"expr":"divs","msg":"You used 100%, which applies only to affiliated group members."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/243","points":1},{"id":"c5","kind":"number","label":"NOL deduction allowed","expr":"min(nol, 0.8*(c3-c4))","fmt":"$","tol":1,"why":"The NOL is limited to 80% of taxable income after the DRD: 80% x ${ti0:,} = ${nlim:,}. The ${nol:,} NOL is below that limit, so all of it is deductible.","steps":["Taxable income before NOL = ${c3:,} - ${c4:,} = ${ti0:,}","80% limit = ${nlim:,}","NOL allowed = lesser of ${nol:,} and ${nlim:,} = ${c5:,}"],"hints":["A post-2017 NOL has an income-based limit.","80% of taxable income after the DRD."],"traps":[{"expr":"0.8*nol","msg":"You took 80% of the NOL. The 80% limit applies to taxable income, not to the NOL itself."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/172","points":1},{"id":"c6","kind":"number","label":"Taxable income","expr":"c3-c4-c5","fmt":"$","tol":1,"why":"Taxable income = income before DRD and NOL - DRD - NOL.","steps":["${c3:,} - ${c4:,} - ${c5:,} = ${c6:,}"],"hints":["Subtract both deductions.","Use your answers to cells 3, 4, and 5."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/63","points":1},{"id":"c7","kind":"number","label":"Regular income tax at 21%","expr":"0.21*c6","fmt":"$","tol":1,"why":"Corporate rate of 21% (IRC §11(b)).","steps":["21% x ${c6:,} = ${c7:,}"],"hints":["Flat rate.","21% of taxable income."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/11","points":1}]},{"id":"REG-V-T-020","area":"V","format":"numeric_table","difficulty":3,"est_minutes":16,"testable_from":"2026-01-01","law_asof":"2026-09-29","law_note":"","cite":["IRC §722","IRC §752(a)","IRC §705(a)","IRC §704(d)","IRC §731(a)(1)"],"blueprint":{"area":"V","group":"C","topic":"Partnership basis and distributions","task":"Compute outside basis, loss limits, and gain on distributions","skill":"Application"},"params":{"cash":80000,"liab0":20000,"inc":30000,"tex":2000,"nond":1500,"chr":3000,"liab_up":10000,"dist1":25000,"dist2":40000,"loss2":85000,"dist3":20000},"vary":{"inc":[24000,30000,36000],"dist2":[30000,40000,50000],"loss2":[80000,85000,95000],"dist3":[15000,20000,25000]},"guards":["loss2 > gb2-dist2"],"derived":[["gb2","cash+liab0+inc+tex-nond-chr+liab_up-dist1"]],"title":"Partnership: outside basis, distributions, and loss limitation","scenario":"Kai Tanaka became a partner in Bayline Partners LP on January 2, Year 1, by contributing cash. The partnership uses the calendar year. Ignore the at-risk and passive activity rules, and self-employment tax.","task":"Using the exhibits, compute Kai's outside basis and the results of the distributions and losses. Enter results as positive amounts unless the cell says otherwise. Round to the nearest dollar.","exhibits":[{"id":"e1","title":"Year 1 and initial data","kind":"table","body":[["Item","Amount"],["Cash contributed on January 2, Year 1","${cash:,}"],["Kai's share of partnership liabilities on January 2, Year 1","${liab0:,}"],["Kai's share of ordinary business income, Year 1","${inc:,}"],["Kai's share of tax-exempt interest, Year 1","${tex:,}"],["Kai's share of nondeductible expenses, Year 1","${nond:,}"],["Kai's share of a charitable contribution made by the partnership, Year 1","${chr:,}"],["Increase in Kai's share of partnership liabilities during Year 1","${liab_up:,}"],["Cash distribution to Kai on December 31, Year 1","${dist1:,}"]]},{"id":"e2","title":"Years 2 and 3 data","kind":"table","body":[["Item","Amount"],["Cash distribution to Kai on June 30, Year 2 (no other Year 2 income items)","${dist2:,}"],["Kai's share of the partnership's ordinary loss for Year 2 (incurred evenly)","${loss2:,}"],["Cash distribution to Kai in Year 3 (Year 3 has no income or loss items)","${dist3:,}"]]}],"cells":[{"id":"c1","kind":"number","label":"Kai's initial outside basis","expr":"cash+liab0","fmt":"$","tol":1,"why":"Basis = cash contributed + share of partnership liabilities (treated as a contribution of cash, IRC §752(a)).","steps":["${cash:,} + ${liab0:,} = ${c1:,}"],"hints":["Liabilities count for a partner's basis.","Cash plus share of liabilities."],"traps":[{"expr":"cash","msg":"You left out Kai's share of partnership liabilities."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/722","points":1},{"id":"c2","kind":"number","label":"Outside basis at the end of Year 1","expr":"c1+inc+tex-nond-chr+liab_up-dist1","fmt":"$","tol":1,"why":"Basis increases for income, tax-exempt income, and increases in liabilities; decreases for nondeductible expenses, separately stated deductions, and distributions.","steps":["${c1:,} + ${inc:,} + ${tex:,} - ${nond:,} - ${chr:,} + ${liab_up:,} - ${dist1:,} = ${c2:,}"],"hints":["Do increases first, then decreases.","Tax-exempt income increases basis; charity and nondeductible items decrease it."],"traps":[{"expr":"c1+inc-dist1","msg":"You omitted tax-exempt income, nondeductible expenses, the charitable contribution, and the liability change."},{"expr":"c1+inc+tex-nond-chr-dist1","msg":"You omitted the increase in liabilities."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/705","points":1},{"id":"c3","kind":"number","label":"Outside basis in Year 2 after the June 30 distribution and before the loss","expr":"c2-dist2","fmt":"$","tol":1,"why":"Distributions reduce basis before the year's losses are considered.","steps":["${c2:,} - ${dist2:,} = ${c3:,}"],"hints":["Order matters within the year.","Distributions before losses."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/705","points":1},{"id":"c4","kind":"number","label":"Year 2 loss Kai can deduct","expr":"min(loss2, c3)","fmt":"$","tol":1,"why":"Loss deduction is limited to outside basis (IRC §704(d)).","steps":["min(${loss2:,}, ${c3:,}) = ${c4:,}"],"hints":["Compare loss with basis.","Lesser of the loss and basis."],"traps":[{"expr":"loss2","msg":"You deducted the full loss."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/704","points":1},{"id":"c5","kind":"number","label":"Suspended loss carried to Year 3","expr":"loss2-c4","fmt":"$","tol":1,"why":"The disallowed loss is suspended and carried forward indefinitely.","steps":["${loss2:,} - ${c4:,} = ${c5:,}"],"hints":["Loss not deducted.","Loss less deduction."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/704","points":1},{"id":"c6","kind":"number","label":"Outside basis at the end of Year 2","expr":"c3-c4","fmt":"$","tol":1,"why":"Basis is reduced by the deductible loss.","steps":["${c3:,} - ${c4:,} = ${c6:,}"],"hints":["Basis cannot go below zero.","Basis before the loss less the loss deducted."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/705","points":1},{"id":"c7","kind":"number","label":"Year 3: gain recognized on the cash distribution","expr":"max(0, dist3-c6)","fmt":"$","tol":1,"why":"Cash distributed in excess of outside basis is gain from the sale of the partnership interest (IRC §731(a)(1)). Suspended losses do not reduce this gain.","steps":["${dist3:,} - ${c6:,} = ${c7:,}"],"hints":["Basis is exhausted.","Distribution over basis is gain."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/731","points":1}]},{"id":"REG-V-T-021","area":"V","format":"numeric_table","difficulty":3,"est_minutes":14,"testable_from":"2026-01-01","law_asof":"2026-09-29","law_note":"","cite":["IRC §1367(a)","IRC §1368(b)","IRC §1366(d)"],"blueprint":{"area":"V","group":"B","topic":"S corporation basis and distributions","task":"Compute stock and debt basis, distribution gain, and loss limitation","skill":"Application"},"params":{"sb":30000,"inc":40000,"texempt":4000,"nondc":2000,"dist":60000,"dist_alt":90000,"loss":80000,"debt":10000},"vary":{"inc":[36000,40000,44000],"dist":[55000,60000,65000],"dist_alt":[86000,90000,95000],"loss":[70000,80000,90000],"debt":[8000,10000,12000]},"guards":["sb+inc+texempt-dist-nondc > 0","dist_alt > sb+inc+texempt","loss > (sb+inc+texempt-dist-nondc)+debt"],"derived":[],"title":"S corporation: stock and debt basis, distributions, and loss limits","scenario":"Ava Lindqvist owns 40% of Cobalt Fabrication Inc., which has been an S corporation since its formation and has no accumulated earnings and profits. All amounts in the exhibits are Ava's share. Ignore the at-risk and passive activity rules.","task":"Using the exhibits, compute Ava's basis, gain, and deductible loss. Round to the nearest dollar.","exhibits":[{"id":"e1","title":"Year 1 data (Ava's share)","kind":"table","body":[["Item","Amount"],["Stock basis on January 1, Year 1","${sb:,}"],["Ordinary business income","${inc:,}"],["Tax-exempt interest","${texempt:,}"],["Nondeductible expenses","${nondc:,}"],["Cash distribution actually made in Year 1","${dist:,}"],["Alternative fact for cell 2 only: the Year 1 distribution had been","${dist_alt:,}"]]},{"id":"e2","title":"Year 2 data (Ava's share)","kind":"table","body":[["Item","Amount"],["Ordinary business loss","${loss:,}"],["Basis in loans Ava made directly to the corporation (debt basis), start of Year 2","${debt:,}"],["Note","The loans are bona fide; ignore any repayment in Year 2."]]}],"cells":[{"id":"c1","kind":"number","label":"Stock basis after Year 1 income items, before distributions and nondeductible expenses","expr":"sb+inc+texempt","fmt":"$","tol":1,"why":"Basis increases for ordinary income and tax-exempt income first (IRC §1367(a)(1)).","steps":["${sb:,} + ${inc:,} + ${texempt:,} = ${c1:,}"],"hints":["Increases come first.","Both income items increase basis."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1367","points":1},{"id":"c2","kind":"number","label":"Alternative fact: gain Ava recognizes if the Year 1 distribution were ${dist_alt:,}","expr":"max(0, dist_alt-c1)","fmt":"$","tol":1,"why":"A distribution from an S corporation with no E&P is a return of basis; the excess over stock basis is capital gain (IRC §1368(b)(2)). Basis for this test is measured after the increases.","steps":["${dist_alt:,} - ${c1:,} = ${c2:,}"],"hints":["Compare distribution to basis.","Distribution above stock basis is capital gain."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1368","points":1},{"id":"c3","kind":"number","label":"Actual Year 1: stock basis at December 31, Year 1","expr":"c1-dist-nondc","fmt":"$","tol":1,"why":"Distributions then nondeductible expenses reduce basis (never below zero).","steps":["${c1:,} - ${dist:,} - ${nondc:,} = ${c3:,}"],"hints":["Order: increases, distributions, then nondeductible expenses and losses.","Subtract both."],"traps":[{"expr":"c1-dist","msg":"You forgot the nondeductible expenses."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1367","points":1},{"id":"c4","kind":"number","label":"Year 2: loss deductible against stock basis","expr":"min(loss, c3)","fmt":"$","tol":1,"why":"Loss reduces stock basis first, but not below zero.","steps":["min(${loss:,}, ${c3:,}) = ${c4:,}"],"hints":["Stock basis is used first.","Lesser of loss and stock basis."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1366","points":1},{"id":"c5","kind":"number","label":"Year 2: loss deductible against debt basis","expr":"min(loss-c4, debt)","fmt":"$","tol":1,"why":"Excess loss then reduces debt basis (IRC §1366(d)(1)(B)).","steps":["min(${loss:,} - ${c4:,}, ${debt:,}) = ${c5:,}"],"hints":["Second layer of basis.","Remaining loss up to debt basis."],"traps":[],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1366","points":1},{"id":"c6","kind":"number","label":"Year 2: suspended loss carried forward","expr":"loss-c4-c5","fmt":"$","tol":1,"why":"Loss in excess of stock and debt basis is suspended (IRC §1366(d)(2)).","steps":["${loss:,} - ${c4:,} - ${c5:,} = ${c6:,}"],"hints":["Loss not absorbed.","Total loss less both deductions."],"traps":[{"expr":"loss-c4","msg":"You did not use debt basis."}],"ecf":true,"link":"https://www.law.cornell.edu/uscode/text/26/1366","points":1}]},{"id":"REG-V-T-022","area":"V","format":"document_review","difficulty":2,"est_minutes":12,"testable_from":"2026-01-01","law_asof":"2026-09-29","law_note":"","cite":["IRC §1361","IRC §1362","IRC §1374"],"blueprint":{"area":"V","group":"B","topic":"S corporation eligibility, election, and termination","task":"Identify eligibility, election, and termination rules","skill":"Analysis"},"params":{},"vary":{},"guards":[],"derived":[],"title":"S corporation eligibility and termination: memo review","scenario":"You are reviewing a memo written by a staff accountant to the owners of Greenfield Tools Inc., a C corporation considering an S election.","task":"For each numbered statement, choose the option that makes the statement correct. Choose 'Keep as written' if it is already correct.","exhibits":[{"id":"e1","title":"Draft memo","kind":"memo","body":"1. An S corporation may have no more than 75 shareholders.\n2. If the corporation has voting and nonvoting common stock with identical rights to distributions and liquidation proceeds, it has two classes of stock and is ineligible for S status.\n3. A nonresident alien may be a shareholder of an S corporation if he or she consents to the election on Form 2553.\n4. To be effective for its first tax year, the S election generally must be filed no later than the 15th day of the third month of that tax year.\n5. A C corporation that converts to S status pays the built-in gains tax on gains recognized within 10 years after the conversion date.\n6. An S election terminates if the corporation has accumulated earnings and profits from a C year and passive investment income above 25% of gross receipts for 2 consecutive years."}],"cells":[{"id":"c1","kind":"dropdown","label":"Statement 1: shareholder limit","options":["Keep as written","Revise: 100 shareholders (family members count as one)","Revise: 250 shareholders"],"answer":"Revise: 100 shareholders (family members count as one)","why":"An S corporation may have no more than 100 shareholders; family members can elect to be treated as one shareholder (IRC §1361(b)(1)(A), (c)(1)).","steps":[],"hints":["Number was increased long ago.","100."],"wrong_msgs":{"Keep as written":"The limit is 100, not 75.","Revise: 250 shareholders":"The limit is 100."},"cite":"IRC §1361(b)(1)(A)","link":"https://www.law.cornell.edu/uscode/text/26/1361","points":1,"opts0":["Revise: 100 shareholders (family members count as one)","Revise: 250 shareholders","Keep as written"]},{"id":"c2","kind":"dropdown","label":"Statement 2: voting and nonvoting stock","options":["Keep as written","Revise: differences in voting rights alone do not create a second class of stock","Revise: nonvoting stock is never allowed"],"answer":"Revise: differences in voting rights alone do not create a second class of stock","why":"An S corporation may have voting and nonvoting common stock, since all shares confer identical rights to distributions and liquidation proceeds (IRC §1361(c)(4)).","steps":[],"hints":["What defines a class of stock?","Rights to distribution and liquidation proceeds."],"wrong_msgs":{"Keep as written":"Voting differences alone do not create a second class.","Revise: nonvoting stock is never allowed":"Nonvoting common stock is allowed."},"cite":"IRC §1361(c)(4)","link":"https://www.law.cornell.edu/uscode/text/26/1361","points":1,"opts0":["Revise: differences in voting rights alone do not create a second class of stock","Revise: nonvoting stock is never allowed","Keep as written"]},{"id":"c3","kind":"dropdown","label":"Statement 3: nonresident alien shareholder","options":["Keep as written","Revise: a nonresident alien is not an eligible shareholder","Revise: a nonresident alien is eligible only if the S corporation has no other shareholders"],"answer":"Revise: a nonresident alien is not an eligible shareholder","why":"Eligible shareholders are individuals who are U.S. citizens or residents, estates, and certain trusts and exempt organizations; nonresident aliens are not eligible (IRC §1361(b)(1)(C)).","steps":[],"hints":["Look at who may hold S stock.","Citizenship or residency requirement."],"wrong_msgs":{"Keep as written":"Consent does not cure ineligibility.","Revise: a nonresident alien is eligible only if the S corporation has no other shareholders":"There is no such exception."},"cite":"IRC §1361(b)(1)(C)","link":"https://www.law.cornell.edu/uscode/text/26/1361","points":1,"opts0":["Revise: a nonresident alien is not an eligible shareholder","Revise: a nonresident alien is eligible only if the S corporation has no other shareholders","Keep as written"]},{"id":"c4","kind":"dropdown","label":"Statement 4: election deadline","options":["Keep as written","Revise: the 15th day of the fourth month","Revise: the last day of the tax year"],"answer":"Keep as written","why":"Form 2553 must be filed at any time during the preceding tax year or by the 15th day of the third month (2 months and 15 days) of the tax year to be effective for that year (IRC §1362(b)).","steps":[],"hints":["Two months and 15 days.","15th day of the third month."],"wrong_msgs":{"Revise: the 15th day of the fourth month":"That is one month too late.","Revise: the last day of the tax year":"Late elections are allowed only through relief procedures."},"cite":"IRC §1362(b)","link":"https://www.law.cornell.edu/uscode/text/26/1362","points":1,"opts0":["Revise: the last day of the tax year","Revise: the 15th day of the fourth month","Keep as written"]},{"id":"c5","kind":"dropdown","label":"Statement 5: built-in gains recognition period","options":["Keep as written","Revise: 5 years","Revise: 15 years"],"answer":"Revise: 5 years","why":"The recognition period for the section 1374 tax is 5 years beginning with the first day of the first S corporation year (permanent since 2015).","steps":[],"hints":["The period is shorter.","5 years."],"wrong_msgs":{"Keep as written":"Ten years was the period under pre-2009 law; the current period is five.","Revise: 15 years":"The recognition period is 5 years."},"cite":"IRC §1374(d)(7)","link":"https://www.law.cornell.edu/uscode/text/26/1374","points":1,"opts0":["Revise: 5 years","Keep as written","Revise: 15 years"]},{"id":"c6","kind":"dropdown","label":"Statement 6: passive income termination","options":["Keep as written","Revise: 3 consecutive years","Revise: 5 consecutive years"],"answer":"Revise: 3 consecutive years","why":"An S election terminates if the corporation has C-corporation earnings and profits and passive investment income exceeds 25% of gross receipts for 3 consecutive taxable years (IRC §1362(d)(3)).","steps":[],"hints":["Test is over multiple years.","3 consecutive years."],"wrong_msgs":{"Keep as written":"Two years is too short.","Revise: 5 consecutive years":"Termination occurs after 3 consecutive years."},"cite":"IRC §1362(d)(3)","link":"https://www.law.cornell.edu/uscode/text/26/1362","points":1,"opts0":["Revise: 5 consecutive years","Revise: 3 consecutive years","Keep as written"]}]},{"id":"REG-V-T-023","area":"V","format":"document_review","difficulty":2,"est_minutes":12,"testable_from":"2026-01-01","law_asof":"2026-09-29","law_note":"","cite":["IRC §721","IRC §723","IRC §707(c)","IRC §731","IRC §1402(a)(13)","IRC §1223(1)"],"blueprint":{"area":"V","group":"C","topic":"Partnership formation and operation","task":"Identify partnership contribution, guaranteed payment, distribution, and SE tax rules","skill":"Analysis"},"params":{},"vary":{},"guards":[],"derived":[],"title":"Partnership formation and operations: memo review","scenario":"You are reviewing a memo prepared by a staff accountant for the partners of Lakeview Ventures, a newly formed general partnership that also has a limited partner.","task":"For each numbered statement, choose the option that makes the statement correct. Choose 'Keep as written' if it is already correct.","exhibits":[{"id":"e1","title":"Draft memo","kind":"memo","body":"1. When a partner contributes appreciated property to the partnership for an interest, the partnership's basis in the property equals its fair market value on the date of contribution.\n2. Guaranteed payments to a partner for services are treated as distributions and are not deductible by the partnership.\n3. A partner is taxed on his or her distributive share of partnership income only when the income is distributed to the partner.\n4. A current cash distribution to a partner in excess of the partner's outside basis results in gain to the partner.\n5. A general partner's distributive share of ordinary business income is generally subject to self-employment tax, while a limited partner's distributive share generally is not.\n6. A partner's holding period for a partnership interest received in exchange for a contributed capital asset includes the holding period of the contributed asset."}],"cells":[{"id":"c1","kind":"dropdown","label":"Statement 1: partnership's basis in contributed property","options":["Keep as written","Revise: the partnership takes the contributing partner's adjusted basis (carryover basis)","Revise: the partnership's basis is the FMV, but only if the property is depreciable"],"answer":"Revise: the partnership takes the contributing partner's adjusted basis (carryover basis)","why":"No gain or loss is recognized on a contribution for a partnership interest (IRC §721(a)), and the partnership's basis is the contributor's adjusted basis (IRC §723).","steps":[],"hints":["Nonrecognition on contribution.","Carryover basis."],"wrong_msgs":{"Keep as written":"FMV basis would trigger gain recognition; the partnership takes a carryover basis.","Revise: the partnership's basis is the FMV, but only if the property is depreciable":"Depreciability does not change the carryover basis rule."},"cite":"IRC §721(a); §723","link":"https://www.law.cornell.edu/uscode/text/26/723","points":1,"opts0":["Keep as written","Revise: the partnership's basis is the FMV, but only if the property is depreciable","Revise: the partnership takes the contributing partner's adjusted basis (carryover basis)"]},{"id":"c2","kind":"dropdown","label":"Statement 2: guaranteed payments","options":["Keep as written","Revise: guaranteed payments are ordinary income to the partner and deductible (or capitalized) by the partnership","Revise: guaranteed payments are capital gain to the partner"],"answer":"Revise: guaranteed payments are ordinary income to the partner and deductible (or capitalized) by the partnership","why":"A guaranteed payment for services or the use of capital is treated as made to a nonpartner for the partner's income and the partnership's deduction or capitalization (IRC §707(c)).","steps":[],"hints":["Payments determined without regard to partnership income.","Treated like payments to an outsider."],"wrong_msgs":{"Keep as written":"Guaranteed payments are not distributions; the partnership deducts them.","Revise: guaranteed payments are capital gain to the partner":"They are ordinary income."},"cite":"IRC §707(c)","link":"https://www.law.cornell.edu/uscode/text/26/707","points":1,"opts0":["Revise: guaranteed payments are capital gain to the partner","Keep as written","Revise: guaranteed payments are ordinary income to the partner and deductible (or capitalized) by the partnership"]},{"id":"c3","kind":"dropdown","label":"Statement 3: when the partner is taxed","options":["Keep as written","Revise: the partner is taxed on the distributive share whether or not it is distributed","Revise: the partner is taxed only on the last day of the partnership year in cash"],"answer":"Revise: the partner is taxed on the distributive share whether or not it is distributed","why":"A partnership is a pass-through: partners report their distributive shares of income whether or not distributed (IRC §702(a), §704).","steps":[],"hints":["Pass-through means...","Taxed as earned."],"wrong_msgs":{"Keep as written":"Taxation does not depend on distribution.","Revise: the partner is taxed only on the last day of the partnership year in cash":"It is not a cash-basis pass-through requirement."},"cite":"IRC §702(a)","link":"https://www.law.cornell.edu/uscode/text/26/702","points":1,"opts0":["Keep as written","Revise: the partner is taxed on the distributive share whether or not it is distributed","Revise: the partner is taxed only on the last day of the partnership year in cash"]},{"id":"c4","kind":"dropdown","label":"Statement 4: cash distribution over basis","options":["Keep as written","Revise: the excess reduces basis below zero","Revise: the excess is taxed as ordinary income in all cases"],"answer":"Keep as written","why":"Money distributed in excess of the partner's adjusted basis in the partnership interest is gain from the sale of the interest (IRC §731(a)(1)).","steps":[],"hints":["Basis cannot be negative.","Excess is gain."],"wrong_msgs":{"Revise: the excess reduces basis below zero":"Outside basis cannot go below zero.","Revise: the excess is taxed as ordinary income in all cases":"It is generally capital gain (subject to hot assets)."},"cite":"IRC §731(a)(1)","link":"https://www.law.cornell.edu/uscode/text/26/731","points":1,"opts0":["Revise: the excess reduces basis below zero","Revise: the excess is taxed as ordinary income in all cases","Keep as written"]},{"id":"c5","kind":"dropdown","label":"Statement 5: self-employment tax","options":["Keep as written","Revise: general partners are exempt and limited partners are subject","Revise: neither is subject to self-employment tax"],"answer":"Keep as written","why":"A general partner's distributive share of trade or business income is net earnings from self-employment; a limited partner's distributive share generally is excluded (IRC §1402(a)(13)), except for guaranteed payments for services.","steps":[],"hints":["Limited partners are passive.","General partners are subject."],"wrong_msgs":{"Revise: general partners are exempt and limited partners are subject":"Reversed.","Revise: neither is subject to self-employment tax":"General partners are subject."},"cite":"IRC §1402(a)(13)","link":"https://www.law.cornell.edu/uscode/text/26/1402","points":1,"opts0":["Revise: neither is subject to self-employment tax","Keep as written","Revise: general partners are exempt and limited partners are subject"]},{"id":"c6","kind":"dropdown","label":"Statement 6: holding period of the partnership interest","options":["Keep as written","Revise: the holding period starts on the date of the contribution regardless of the asset","Revise: the holding period is always long-term"],"answer":"Keep as written","why":"The holding period of a partnership interest received for a contribution of capital assets or section 1231 property includes the holding period of the contributed property (IRC §1223(1)).","steps":[],"hints":["Tacking rule.","Applies to capital and §1231 assets."],"wrong_msgs":{"Revise: the holding period starts on the date of the contribution regardless of the asset":"Tacking applies to capital and §1231 assets.","Revise: the holding period is always long-term":"It depends on the contributed property's holding period."},"cite":"IRC §1223(1)","link":"https://www.law.cornell.edu/uscode/text/26/1223","points":1,"opts0":["Revise: the holding period starts on the date of the contribution regardless of the asset","Keep as written","Revise: the holding period is always long-term"]}]},{"id":"REG-V-T-024","area":"V","format":"research","difficulty":2,"est_minutes":10,"testable_from":"2026-01-01","law_asof":"2026-09-29","law_note":"","cite":["IRC §351","IRC §316","IRC §704(d)","IRC §1374","IRC §1367","IRC §731"],"blueprint":{"area":"V","group":"A","topic":"Research: entity taxation","task":"Research and cite authority for corporate, S corporation, and partnership issues","skill":"Application"},"params":{},"vary":{},"guards":[],"derived":[],"title":"Locate the authority: corporations and pass-through entities","scenario":"The owners of a closely held business ask six questions about corporate and pass-through tax rules. Identify the primary authority for each.","task":"For each question, enter the Internal Revenue Code citation (for example, 'IRC 1223(1)'). Give a subsection or paragraph only when the question asks for it.","exhibits":[{"id":"e1","title":"Questions","kind":"email","body":"1. Which section and subsection provide that no gain or loss is recognized when property is transferred to a corporation solely for stock and the transferors control the corporation immediately afterward?\n2. Which section and subsection define a corporate 'dividend' (distribution out of earnings and profits)?\n3. Which section and subsection limit a partner's deduction for partnership losses to the adjusted basis of the partner's interest?\n4. Which section and subsection impose the tax on net recognized built-in gain of an S corporation?\n5. Which section, subsection, and paragraph list the decreases in an S shareholder's stock basis (distributions, losses, deductions)?\n6. Which section, subsection, and paragraph provide that a partner recognizes gain when money distributed exceeds the adjusted basis of the partner's interest?"}],"cells":[{"id":"c1","kind":"citation","label":"Question 1: incorporation nonrecognition","ask":"IRC section (and subsection if asked)","accept":["351(a)"],"partial":["351"],"link":"https://www.law.cornell.edu/uscode/text/26/351","why":"IRC §351(a) nonrecognition on transfers to a controlled corporation.","steps":[],"hints":["Subchapter C, part III.","Section 351, subsection (a)."],"points":1},{"id":"c2","kind":"citation","label":"Question 2: definition of dividend","ask":"IRC section (and subsection if asked)","accept":["316(a)"],"partial":["316"],"link":"https://www.law.cornell.edu/uscode/text/26/316","why":"IRC §316(a) defines dividend as any distribution out of E&P accumulated after February 28, 1913, or E&P of the taxable year.","steps":[],"hints":["Section 316.","Subsection (a)."],"points":1},{"id":"c3","kind":"citation","label":"Question 3: partner loss limitation","ask":"IRC section (and subsection if asked)","accept":["704(d)"],"partial":["704"],"link":"https://www.law.cornell.edu/uscode/text/26/704","why":"IRC §704(d): a partner's distributive share of loss is allowed only to the extent of the adjusted basis at the end of the year.","steps":[],"hints":["Section 704 covers partner's distributive share.","Subsection (d)."],"points":1},{"id":"c4","kind":"citation","label":"Question 4: built-in gains tax","ask":"IRC section (and subsection if asked)","accept":["1374(a)"],"partial":["1374"],"link":"https://www.law.cornell.edu/uscode/text/26/1374","why":"IRC §1374(a) imposes the tax on net recognized built-in gain.","steps":[],"hints":["Section 1374.","Subsection (a)."],"points":1},{"id":"c5","kind":"citation","label":"Question 5: decreases in S stock basis","ask":"IRC section (and subsection if asked)","accept":["1367(a)(2)"],"partial":["1367","1367(a)"],"link":"https://www.law.cornell.edu/uscode/text/26/1367","why":"IRC §1367(a)(2) lists decreases (distributions, losses and deductions, nondeductible expenses, oil and gas depletion).","steps":[],"hints":["Section 1367.","Subsection (a), paragraph (2)."],"points":1},{"id":"c6","kind":"citation","label":"Question 6: gain on distribution over basis","ask":"IRC section (and subsection if asked)","accept":["731(a)(1)"],"partial":["731","731(a)"],"link":"https://www.law.cornell.edu/uscode/text/26/731","why":"IRC §731(a)(1): gain is recognized to the extent money distributed exceeds the adjusted basis.","steps":[],"hints":["Section 731.","Subsection (a), paragraph (1)."],"points":1}]}]};
